"""Military unit catalog source data."""

from __future__ import annotations

UNITS: list[tuple] = [
    ('confederacy-of-independent-systems', 'army', 'b1-battle-droids', 'B1 Battle Droids', 'Infantry', None, "Mass-produced OOM-series battle droids formed the Separatist front line across Geonosis, Felucia, and a thousand Clone Wars battlefields. Programmed for rigid formations and overwhelming numbers, B1 units carried E-5 blaster rifles and often served as expendable screening forces ahead of heavier droid formations. Their distinctive skeletal frame and flat vocoder tones became synonymous with Count Dooku's war machine.", '#3ecfb2', ['b2-super-battle-droids', 'droidekas', 'vulture-droid-starfighter-wing']),
    ('confederacy-of-independent-systems', 'army', 'b2-super-battle-droids', 'B2 Super Battle Droids', 'Heavy infantry', None, 'Up-armored B2 units replaced fragile B1s in assault waves, mounting wrist-mounted blaster cannons and reinforced durasteel plating. Deployed at Christophsis, Mygeeto, and Utapau, super battle droids could advance under fire that shredded lighter infantry. Trade Federation and Techno Union foundries produced them in vast numbers to break Republic clone lines.', '#14b8a6', ['b1-battle-droids', 'droidekas', 'aat-armored-battalion']),
    ('confederacy-of-independent-systems', 'army', 'droidekas', 'Droidekas', 'Heavy infantry', None, 'Destroyer droids rolled into combat encased in portable deflector shields, unleashing twin blaster fire until shields collapsed under concentrated fire. Grievous deployed droidekas as palace guards and battlefield anchors, especially on Utapau and aboard his flagship. Their rolling locomotion and shield domes made them among the most feared droid infantry types of the war.', '#0d9488', ['b2-super-battle-droids', 'magna-guards', 'providence-class-dreadnought']),
    ('confederacy-of-independent-systems', 'army', 'magna-guards', 'IG-100 MagnaGuards', 'Bodyguard', None, 'Electrostaff-wielding IG-100 MagnaGuards served General Grievous as elite bodyguards and Jedi-hunting enforcers. Trained in esoteric combat forms and equipped with cape-like robes concealing additional weapons, they accompanied Grievous to Saleucami, Utapau, and Coruscant. MagnaGuards could continue fighting even after decapitation thanks to redundant processor clusters.', '#2dd4bf', ['droidekas', 'bx-commando-droids', 'invisible-hand-flagship-group']),
    ('confederacy-of-independent-systems', 'army', 'bx-commando-droids', 'BX-series Commando Droids', 'Special forces', None, 'Black-plated BX commando droids operated as infiltration units, snipers, and boarding parties with far greater autonomy than standard B1s. They captured the Rishi moon listening post and breached Republic vessels during deep-space raids. Their humanoid agility and marksmanship made them the closest Separatist equivalent to clone commandos.', '#0891b2', ['b1-battle-droids', 'magna-guards', 'recusant-class-destroyer']),
    ('confederacy-of-independent-systems', 'army', 'oom-command-droids', 'OOM Command Battle Droids', 'Command', None, 'Yellow-marked OOM command droids coordinated battalion-scale droid formations from forward command posts and Lucrehulk control centers. They relayed tactical updates through comlinks and reduced the notorious confusion of mass B1 deployments. Separatist admirals relied on command droids to synchronize landing craft, armor, and starfighter waves.', '#06b6d4', ['b1-battle-droids', 'b2-super-battle-droids', 'lucrehulk-class-battleship']),
    ('confederacy-of-independent-systems', 'army', 'geonosian-warriors', 'Geonosian Warriors', 'Allied infantry', None, 'Native Geonosian warriors fought from sonic blaster nests and petranaki arena traditions, defending foundries that supplied the Separatist droid army. Winged soldiers harried clone troopers with ambushes above droid factory complexes. Their alliance with Count Dooku made Geonosis the symbolic birthplace of the Clone Wars.', '#5eead4', ['b1-battle-droids', 'crab-droid-assault-division', 'c9979-landing-craft-squadron']),
    ('confederacy-of-independent-systems', 'army', 'corporate-alliance-troopers', 'Corporate Alliance Troopers', 'Corporate army', None, "Corporate Alliance security divisions augmented droid armies with organic soldiers, artillery crews, and occupation garrisons on member worlds. They guarded mining installations and hyperlane toll stations across the Outer Rim. Passel Argente's conglomerate integrated these troops into larger Separatist task forces during the Mid Rim campaigns.", '#2dd4bf', ['banking-clan-security-forces', 'techno-union-droids', 'munificent-class-frigate']),
    ('confederacy-of-independent-systems', 'army', 'banking-clan-security-forces', 'InterGalactic Banking Clan Security Forces', 'Corporate army', None, "Muun security legions protected vault worlds, treasury fleets, and San Hill's financial interests while contributing heavy armor to Separatist offensives. Hailfire tanks and mobile artillery often bore Banking Clan livery at the Battle of Muunilinst. Their soldiers blended corporate discipline with Separatist strategic objectives.", '#14b8a6', ['hailfire-droid-battery', 'corporate-alliance-troopers', 'diamond-class-cruiser']),
    ('confederacy-of-independent-systems', 'army', 'neimoidian-soldier-corps', 'Neimoidian Soldier Corps', 'Infantry', None, 'Neimoidian soldiers served aboard Trade Federation battleships and guarded command bridges during planetary blockades. Though rarely frontline shock troops, they enforced Trade Federation edicts from Naboo to the Outer Rim sieges. Their presence symbolized the corporate aristocracy driving much of Separatist politics.', '#0d9488', ['b1-battle-droids', 'trade-federation-droid-army', 'lucrehulk-class-battleship']),
    ('confederacy-of-independent-systems', 'army', 'aat-armored-battalion', 'AAT Armored Assault Battalion', 'Armor', None, "Armored Assault Tanks spearheaded Separatist mechanized columns with heavy laser cannons and passenger compartments for battle droids. AAT battalions rolled across the grasslands of Naboo and the urban war zones of Coruscant's outer districts during the war's final year. Their blue Trade Federation markings remained visible even under Separatist reorganization.", '#06b6d4', ['b2-super-battle-droids', 'persuader-tank-company', 'c9979-landing-craft-squadron']),
    ('confederacy-of-independent-systems', 'army', 'hmp-droid-gunship-wing', 'HMP Droid Gunship Wing', 'Aerial assault', None, 'Heavy Missile Platform gunships provided close air support with rockets, laser turrets, and droid deployment racks over Felucia and Ringo Vinda. These angular gunships hunted Republic LAAT/i gunships in brutal low-altitude duels. Separatist ground commanders used HMP wings to break clone entrenchments before armor advances.', '#0891b2', ['vulture-droid-starfighter-wing', 'aat-armored-battalion', 'providence-class-dreadnought']),
    ('confederacy-of-independent-systems', 'army', 'crab-droid-assault-division', 'LM-432 Crab Droid Assault Division', 'Heavy armor', None, "Crab droids scuttled across battlefields on six legs, climbing ruins and delivering sustained blaster fire from elevated positions. Utapau's sinkhole campaigns and industrial zones saw crab droids used as mobile turrets. Their low profile made them effective in urban and canyon warfare against clone armor.", '#2dd4bf', ['spider-droid-artillery-battery', 'geonosian-warriors', 'recusant-class-destroyer']),
    ('confederacy-of-independent-systems', 'army', 'spider-droid-artillery-battery', 'OG-9 Homing Spider Droid Battery', 'Artillery', None, 'Homing spider droids served as self-propelled artillery, firing heavy plasma bolts at Republic walkers and fortifications from extreme range. Batteries deployed on Geonosis and Mygeeto could bracket entire clone battalions before they reached Separatist lines. Their spindly silhouettes dominated Separatist parade holograms as symbols of industrial warfare.', '#5eead4', ['crab-droid-assault-division', 'hailfire-droid-battery', 'subjugator-class-heavy-cruiser']),
    ('confederacy-of-independent-systems', 'army', 'hailfire-droid-battery', 'IG-227 Hailfire Droid Battery', 'Mobile artillery', None, 'Hailfire droids unleashed volleys of missiles from fast-moving tread platforms, devastating clone armor at Muunilinst and other banking worlds. Each unit carried limited ammunition but could cripple an entire column in opening salvos. Banking Clan livery marked many of the deadliest Hailfire batteries in Separatist service.', '#14b8a6', ['spider-droid-artillery-battery', 'banking-clan-security-forces', 'munificent-class-frigate']),
    ('confederacy-of-independent-systems', 'army', 'persuader-tank-company', 'NR-N99 Persuader Tank Company', 'Armor', None, 'Corporate Alliance Persuader tanks—nicknamed snail tanks—advanced with twin heavy laser cannons and layered armor over tread assemblies. They escorted convoys through contested industrial corridors and supported droid infantry during Mid Rim offensives. Their slow but relentless advance typified Separatist siege doctrine.', '#0d9488', ['aat-armored-battalion', 'corporate-alliance-troopers', 'hardcell-class-transport']),
    ('confederacy-of-independent-systems', 'army', 'techno-union-droids', 'Techno Union Droid Army', 'Industrial army', None, "Techno Union foundries on Skako Minor and Foerost supplied experimental droid variants, worker-soldier conversions, and battlefield repair swarms to the Separatist cause. Wat Tambor's industrial empire treated warfare as production logistics, fielding customized droid divisions alongside conventional battle droids. Their research divisions pioneered many B-series upgrades deployed late in the war.", '#06b6d4', ['b2-super-battle-droids', 'bx-commando-droids', 'diamond-class-cruiser']),
    ('confederacy-of-independent-systems', 'army', 'snail-tank-battalion', 'Snail Tank Assault Battalion', 'Mechanized infantry', None, "Mixed formations of Persuader tanks and battle droid riders formed snail tank battalions used in Corporate Alliance spearheads. These units breached minefields and shield walls on worlds where heavier Separatist armor could not deploy quickly. Passel Argente's forces relied on them during protracted Mid Rim sieges.", '#0891b2', ['persuader-tank-company', 'corporate-alliance-troopers', 'recusant-class-destroyer']),
    ('confederacy-of-independent-systems', 'navy', 'providence-class-dreadnought', 'Providence-class Dreadnought', 'Capital ship', 'Star Destroyer', "Providence-class dreadnoughts like the Invisible Hand served as flagship command vessels for Count Dooku and General Grievous, combining turbolaser broadsides with droid starfighter wings. These triangular hulls matched Republic Venators in raw firepower while emphasizing droid crew efficiency. They led Separatist fleet actions from Christophsis to Coruscant's orbit.", '#5eead4', ['invisible-hand-flagship-group', 'munificent-class-frigate', 'vulture-droid-starfighter-wing']),
    ('confederacy-of-independent-systems', 'navy', 'lucrehulk-class-battleship', 'Lucrehulk-class Battleship', 'Capital ship', 'Carrier', 'Trade Federation Lucrehulk battleships functioned as droid carrier hubs, command centers, and blockade platforms since the Naboo invasion. Their circular profiles housed thousands of landing craft and starfighters within concentric docking rings. During the Clone Wars they anchored Separatist fleet groups across the Outer Rim.', '#2dd4bf', ['c9979-landing-craft-squadron', 'vulture-droid-starfighter-wing', 'neimoidian-soldier-corps']),
    ('confederacy-of-independent-systems', 'navy', 'munificent-class-frigate', 'Munificent-class Frigate', 'Escort ship', 'Frigate', 'Munificent-class frigates—banking clan frigates—provided fast escort and commerce raiding capability with heavy turbolasers for their size. They hunted Republic convoys and screened larger dreadnoughts in fleet engagements. Their distinctive forward spines became icons of Separatist naval power.', '#14b8a6', ['providence-class-dreadnought', 'recusant-class-destroyer', 'banking-clan-security-forces']),
    ('confederacy-of-independent-systems', 'navy', 'recusant-class-destroyer', 'Recusant-class Light Destroyer', 'Escort ship', 'Destroyer', 'Recusant-class light destroyers offered Separatist admirals cheap, mass-produced hulls for swarm tactics against Republic battle groups. Thin profiles and aggressive forward batteries suited hit-and-run strikes along hyperlanes. They often paired with Munificent frigates in mixed flotillas.', '#0d9488', ['munificent-class-frigate', 'vulture-droid-starfighter-wing', 'bx-commando-droids']),
    ('confederacy-of-independent-systems', 'navy', 'hardcell-class-transport', 'Hardcell-class Transport', 'Support ship', 'Transport', 'Hardcell-class transports moved battle droids, fuel, and spare parts to forward Separatist staging zones with minimal escort requirements. Techno Union and Corporate Alliance logistics chains depended on these angular cargo vessels. They were frequent targets of Republic interdiction raids.', '#06b6d4', ['persuader-tank-company', 'techno-union-droids', 'separatist-blockade-fleet']),
    ('confederacy-of-independent-systems', 'navy', 'vulture-droid-starfighter-wing', 'Vulture Droid Starfighter Wing', 'Starfighter unit', 'Starfighter wing', 'Variable-geometry vulture droids launched in swarms from Lucrehulks and Providence carriers, overwhelming Republic fighter screens through sheer numbers. They fought at Coruscant, Naboo, and countless fleet actions without organic pilots. Their screeching dive attacks defined Separatist starfighter doctrine.', '#0891b2', ['tri-fighter-escort-wing', 'hyena-class-bomber-wing', 'lucrehulk-class-battleship']),
    ('confederacy-of-independent-systems', 'navy', 'tri-fighter-escort-wing', 'Droid Tri-Fighter Escort Wing', 'Starfighter unit', 'Starfighter wing', 'Tri-fighters combined three reactors and precision targeting droids to hunt Republic ace pilots and intercept bombers. Escort wings protected Hyena bombers and capital ships during deep-space engagements. Their three-armed silhouette struck fear into clone trooper pilots across the Mid Rim.', '#5eead4', ['vulture-droid-starfighter-wing', 'hyena-class-bomber-wing', 'providence-class-dreadnought']),
    ('confederacy-of-independent-systems', 'navy', 'hyena-class-bomber-wing', 'Hyena-class Bomber Wing', 'Starfighter unit', 'Bomber wing', 'Hyena bombers delivered proton torpedoes and concussion missiles against Republic capital ships and ground installations. Bomber wings coordinated with vulture swarms to saturate deflector shields before capital ship broadsides. They were essential to Separatist anti-orbital campaigns.', '#2dd4bf', ['vulture-droid-starfighter-wing', 'tri-fighter-escort-wing', 'subjugator-class-heavy-cruiser']),
    ('confederacy-of-independent-systems', 'navy', 'c9979-landing-craft-squadron', 'C-9979 Landing Craft Squadron', 'Support ship', 'Transport', 'C-9979 landing craft deployed entire droid battalions from orbit to contested surfaces during invasions of Kashyyyk, Felucia, and Saleucami. Squadrons launched in timed waves to maintain continuous pressure on clone defenses. Their massive silhouettes darkened skies above besieged cities.', '#14b8a6', ['lucrehulk-class-battleship', 'aat-armored-battalion', 'geonosian-warriors']),
    ('confederacy-of-independent-systems', 'navy', 'subjugator-class-heavy-cruiser', 'Subjugator-class Heavy Cruiser', 'Capital ship', 'Dreadnought', 'Subjugator-class heavy cruisers like the Malevolence wielded ion pulse cannons capable of disabling entire Republic fleets before conventional batteries fired. Grievous used these dreadnoughts in terror campaigns along the Kaliida Shoals medical convoy routes. Their dark hulls and ion arcs became legends among clone naval officers.', '#0d9488', ['providence-class-dreadnought', 'hyena-class-bomber-wing', 'spider-droid-artillery-battery']),
    ('confederacy-of-independent-systems', 'navy', 'diamond-class-cruiser', 'Diamond-class Cruiser', 'Escort ship', 'Cruiser', 'Diamond-class cruisers from the Commerce Guild combined patrol duties with fleet escort roles, protecting Techno Union convoys and Separatist staging areas. Their gem-shaped profiles carried moderate turbolaser arrays and droid starfighter complements. They were common sights in Corporate Sector fleet groups.', '#06b6d4', ['techno-union-droids', 'banking-clan-security-forces', 'separatist-blockade-fleet']),
    ('confederacy-of-independent-systems', 'navy', 'separatist-blockade-fleet', 'Separatist Blockade Fleet', 'Task force', 'Task force', "Combined Separatist blockade fleets encircled contested worlds with Lucrehulks, frigates, and droid starfighter swarms to starve Republic relief convoys. Christophsis and Ryloth saw prolonged blockades that tested both sides' logistics and morale. Blockade commanders coordinated orbital artillery with surface droid armies.", '#0891b2', ['lucrehulk-class-battleship', 'munificent-class-frigate', 'vulture-droid-starfighter-wing']),
    ('confederacy-of-independent-systems', 'navy', 'invisible-hand-flagship-group', 'Invisible Hand Flagship Group', 'Task force', 'Flagship', "The Invisible Hand flagship group embodied Separatist naval ambition—Providence dreadnought escorts, droid wings, and boarding parties under Grievous and Dooku. This task force captured Chancellor Palpatine above Coruscant in the war's climactic space battle. Its name survived in Republic propaganda long after the ship's destruction.", '#5eead4', ['providence-class-dreadnought', 'magna-guards', 'tri-fighter-escort-wing']),
    ('galactic-republic', 'army', 'clone-trooper-corps', 'Clone Trooper Corps', 'Infantry', None, "Two million clone troopers formed the Grand Army of the Republic, bred on Kamino from Jango Fett's template and deployed galaxy-wide after Geonosis. White-armored legions fought with disciplined formations, DC-15 blasters, and rapid reinforcement via Acclamator assault ships. The corps became the Republic's answer to Separatist droid swarms across three years of total war.", '#4a90d9', ['501st-legion', '212th-battalion', 'republic-venator-battle-group']),
    ('galactic-republic', 'army', 'arc-troopers', 'Advanced Recon Commandos', 'Special forces', None, "ARC troopers received enhanced training, independent command authority, and customized armor for deep reconnaissance and sabotage missions. Units like Alpha Squad operated behind enemy lines with sabotaged droid factories and captured Separatist codes. Their blue-accented armor marked the Republic's most versatile clone specialists.", '#2563eb', ['clone-commandos', '501st-legion', 'clone-trooper-corps']),
    ('galactic-republic', 'army', 'clone-commandos', 'Clone Commandos', 'Special forces', None, 'Clone commando squads in katarn-class armor executed precision strikes as Delta Squad, Omega Squad, and the irregular Clone Force 99. Trained by Mandalorian sergeants on Kamino, they carried diverse loadouts for infiltration, demolition, and hostage recovery. Commandos filled gaps that standard infantry and ARC teams could not cover.', '#1d4ed8', ['arc-troopers', '501st-legion', 'laat-gunship-assault-wing']),
    ('galactic-republic', 'army', '501st-legion', '501st Legion', 'Legion', None, "The 501st Legion served under Anakin Skywalker with distinctive blue markings, earning fame at Christophsis, Umbara, and the Jedi Temple raid. Known later as Vader's Fist, the legion embodied elite shock assault doctrine throughout the Clone Wars. Their loyalty to Skywalker made them pivotal in the war's final turning points.", '#3b82f6', ['clone-trooper-corps', '212th-battalion', 'arc-170-starfighter-wing']),
    ('galactic-republic', 'army', '212th-battalion', '212th Attack Battalion', 'Battalion', None, "Obi-Wan Kenobi's 212th Attack Battalion wore orange pauldrons and distinguished itself at Christophsis, Utapau, and the Outer Rim sieges. Combined arms teams paired clone infantry with LAAT gunships and AT-TE walkers under Kenobi's tactical doctrine. The battalion's mud-splattered armor became iconic in holodocumentaries of the war.", '#60a5fa', ['501st-legion', '104th-battalion', 'at-te-walker-battalion']),
    ('galactic-republic', 'army', '104th-battalion', '104th Wolfpack Battalion', 'Battalion', None, "Plo Koon's 104th Wolfpack operated with grey and maroon markings, specializing in rescue operations and harsh-environment warfare. The battalion survived the Malevolence crisis and fought across Felucia and Cato Neimoidia. Wolfpack clones exemplified the close bond between Jedi generals and their troops.", '#0284c7', ['212th-battalion', 'clone-trooper-corps', 'pelta-class-frigate-group']),
    ('galactic-republic', 'army', '327th-star-corps', '327th Star Corps', 'Corps', None, "Aayla Secura's 327th Star Corps fought with yellow-accented armor across Felucia, Quell, and the Outer Rim. Secura's tactical flexibility and the corps' rapid deployment made them a favorite for jungle and urban theaters. Their final deployment on Felucia ended tragically with Order 66.", '#38bdf8', ['212th-battalion', 'wookiee-warriors', 'laat-gunship-assault-wing']),
    ('galactic-republic', 'army', '41st-elite-corps', '41st Elite Corps', 'Corps', None, "The 41st Elite Corps under Jedi General Luminara Unduli and Commander Gree specialized in siege warfare and reconnaissance on worlds like Geonosis and Kashyyyk. Green-marked armor identified these veterans of some of the war's bloodiest campaigns. Kashyyyk's treetop battlefields showcased their combined arms mastery.", '#0ea5e9', ['wookiee-warriors', 'at-te-walker-battalion', 'venator-class-star-destroyer']),
    ('galactic-republic', 'army', 'wookiee-warriors', 'Wookiee Warriors', 'Allied infantry', None, 'Wookiee warriors from Kashyyyk fought alongside clone troopers with bowcasters, ryyk blades, and treetop fortifications during the Outer Rim sieges. Their strength and loyalty made them invaluable allies when the Republic defended Wookiee homeworlds from Separatist invasion. Yoda personally commanded Wookiee-clone joint operations on Kashyyyk.', '#854d0e', ['41st-elite-corps', '327th-star-corps', 'kashyyyk-defense-fleet']),
    ('galactic-republic', 'army', 'jedi-generals', 'Jedi Generals', 'Command', None, "Jedi Knights and Masters served as generals leading clone armies from Geonosis to the Outer Rim, blending Force intuition with military command structures. Their lightsabers and starfighters inspired troop morale while drawing Separatist assassins and droid hunter-killer units. The Jedi's dual role as peacekeepers turned warriors defined the moral complexity of the Clone Wars.", '#22c55e', ['501st-legion', '212th-battalion', 'republic-venator-battle-group']),
    ('galactic-republic', 'army', 'at-te-walker-battalion', 'AT-TE Walker Battalion', 'Armor', None, "All Terrain Tactical Enforcer walkers served as the Republic's primary heavy armor platform, climbing mesas on Geonosis and firing mass-driver cannons across open battlefields. Battalions coordinated with LAAT gunships to deliver walkers into hot landing zones under fire. Their six-legged stability made them icons of Republic ground power.", '#64748b', ['at-rt-recon-company', '212th-battalion', 'acclamator-assault-group']),
    ('galactic-republic', 'army', 'at-rt-recon-company', 'AT-RT Reconnaissance Company', 'Reconnaissance', None, 'All Terrain Recon Transports provided clone scouts with fast, two-legged platforms for patrol and sniper support. Companies screened larger walker battalions and pursued Separatist droid remnants through canyons and city ruins. AT-RT pilots often wore lighter armor for agility.', '#475569', ['at-te-walker-battalion', 'arc-troopers', 'laat-gunship-assault-wing']),
    ('galactic-republic', 'army', 'laat-gunship-assault-wing', 'LAAT Gunship Assault Wing', 'Aerial assault', None, 'Low Altitude Assault Transport gunships—LAAT/i and LAAT/c variants—delivered clones, walkers, and fire support in every major campaign from Geonosis forward. Gunship wings mounted rockets, mass-driver cannons, and door guns for close air support. Their whale-like profiles became synonymous with Republic rapid deployment.', '#0369a1', ['501st-legion', 'clone-commandos', 'venator-class-star-destroyer']),
    ('galactic-republic', 'army', 'galactic-marines', 'Galactic Marines', 'Heavy infantry', None, "Galactic Marines under Bacara wore distinctive red armor and specialized in boarding actions, zero-gravity combat, and extreme-environment warfare. They assaulted Separatist capital ships and defended critical installations with ruthless efficiency. Marines executed Order 66 on Mygeeto under Bacara's command.", '#1e40af', ['clone-trooper-corps', '501st-legion', 'republic-venator-battle-group']),
    ('galactic-republic', 'army', 'clone-flametroopers', 'Clone Flametroopers', 'Specialist', None, 'Clone flametroopers cleared bunker complexes and droid foundries with BT-X42 flamethrowers on worlds like Geonosis and Muunilinst. Their specialized armor resisted heat and chemical backlash during close-quarters assaults. Flametrooper platoons were deployed sparingly due to collateral damage concerns.', '#2563eb', ['clone-trooper-corps', 'at-te-walker-battalion', 'acclamator-assault-group']),
    ('galactic-republic', 'army', 'clone-paratroopers', 'Clone Paratroopers', 'Airborne', None, 'Clone paratroopers dropped from LAAT/i gunships and HAVw A6 Juggernaut staging areas to seize objectives behind Separatist lines. Airborne companies at Kiros and other contested worlds disrupted droid supply chains before main assaults landed. Their specialized helmets and compact gear distinguished them from standard infantry.', '#1d4ed8', ['laat-gunship-assault-wing', 'arc-troopers', 'v-wing-starfighter-wing']),
    ('galactic-republic', 'army', 'clone-engineer-corps', 'Clone Engineer Corps', 'Combat engineers', None, 'Clone combat engineers repaired walkers, breached fortifications, and maintained forward supply depots under fire across the front. Engineer corps units carried cutting tools, explosives, and field medical kits for combined support roles. Their work kept Republic armor columns moving during lengthy sieges.', '#3b82f6', ['at-te-walker-battalion', 'clone-trooper-corps', 'hardcell-class-republic-transport']),
    ('galactic-republic', 'army', 'senate-commando-guard', 'Senate Commando Guard', 'Elite guard', None, "Blue-armored Senate Commandos protected Chancellor Palpatine, diplomatic envoys, and critical Coruscant installations with precision marksmanship and close-quarters tactics. Though smaller in number than clone legions, they represented the Republic's elite security force before the Red Guard's rise. Commandos saw action on hostage rescue missions and anti-terror operations.", '#60a5fa', ['jedi-generals', 'clone-trooper-corps', 'coruscant-home-defense-fleet']),
    ('galactic-republic', 'navy', 'venator-class-star-destroyer', 'Venator-class Star Destroyer', 'Capital ship', 'Star Destroyer', "Venator-class Star Destroyers served dual roles as fleet carriers and battleships, launching V-wings and ARC-170s from ventral hangars while trading broadside fire with Separatist dreadnoughts. These red-striped hulls symbolized Republic naval might from Christophsis to Coruscant's defense. Admirals like Wullf Yularen commanded from Venator bridges throughout the war.", '#0284c7', ['acclamator-assault-group', 'arc-170-starfighter-wing', 'republic-venator-battle-group']),
    ('galactic-republic', 'navy', 'acclamator-assault-group', 'Acclamator-class Assault Group', 'Capital ship', 'Assault ship', "Acclamator-class assault ships delivered entire clone battalions and AT-TE walkers directly into combat zones during the war's opening campaigns. Assault groups combined troop transport with moderate turbolaser armament for planetary invasions. Geonosis proved their design philosophy: get clones on the ground fast.", '#0369a1', ['venator-class-star-destroyer', 'laat-gunship-assault-wing', 'at-te-walker-battalion']),
    ('galactic-republic', 'navy', 'pelta-class-frigate-group', 'Pelta-class Frigate Group', 'Support ship', 'Frigate', 'Pelta-class frigates served as medical evacuators, supply tenders, and fleet support ships during crises like the Malevolence attacks on Kaliida Shoals convoys. Frigate groups kept clone armies supplied and wounded troopers alive across extended campaigns. Their white hulls with red medical markings were protected under wartime conventions.', '#0ea5e9', ['venator-class-star-destroyer', '104th-battalion', 'consular-class-cruiser-escort']),
    ('galactic-republic', 'navy', 'consular-class-cruiser-escort', 'Consular-class Charger c70 Escort', 'Escort ship', 'Corvette', 'Consular-class cruisers in diplomatic configuration often served as fast escorts and command couriers for Jedi generals and Republic intelligence. Refitted with weapon pods, they screened larger fleets and inserted special forces teams. Their red-striped spines were familiar sights in early war newsreels.', '#38bdf8', ['pelta-class-frigate-group', 'jedi-generals', 'v-wing-starfighter-wing']),
    ('galactic-republic', 'navy', 'arc-170-starfighter-wing', 'ARC-170 Starfighter Wing', 'Starfighter unit', 'Starfighter wing', "Aggressive ReConnaissance-170 starfighters provided heavy long-range fighter support with tail gunners and s-foil configurations for fleet battles. ARC-170 wings escorted Y-wing bombers and defended Venator hangars during Coruscant's space battle. Their bulk and firepower made them the Republic's primary heavy starfighter.", '#2563eb', ['v-wing-starfighter-wing', 'y-wing-bomber-wing', 'venator-class-star-destroyer']),
    ('galactic-republic', 'navy', 'v-wing-starfighter-wing', 'V-wing Starfighter Wing', 'Starfighter unit', 'Starfighter wing', 'Alpha-3 Nimbus V-wings served as fast interceptors screening Republic fleets and pursuing Separatist tri-fighters in tight orbital engagements. V-wing wings transitioned into Imperial service after the war, testament to their reliable design. Clone and later volunteer pilots flew them in tight formation tactics.', '#1d4ed8', ['arc-170-starfighter-wing', 'consular-class-cruiser-escort', 'republic-venator-battle-group']),
    ('galactic-republic', 'navy', 'y-wing-bomber-wing', 'BTL Y-wing Bomber Wing', 'Starfighter unit', 'Bomber wing', 'BTL-B Y-wing bombers delivered proton torpedoes and ion payloads against Separatist capital ships and ground installations throughout the Clone Wars. Bomber wings at Malastare and elsewhere cracked droid factory shields before infantry assaults. Many of these airframes later served the Rebel Alliance decades later.', '#1e40af', ['arc-170-starfighter-wing', 'venator-class-star-destroyer', 'republic-venator-battle-group']),
    ('galactic-republic', 'navy', 'republic-venator-battle-group', 'Open Circle Fleet Battle Group', 'Task force', 'Task force', "Open Circle Fleet battle groups under Jedi admirals combined Venators, escort frigates, and multi-wing starfighter complements for major fleet engagements. These task forces fought at Coruscant, Saleucami, and across the Outer Rim theater. Their circular insignia marked the Republic Navy's most recognizable formation.", '#0284c7', ['venator-class-star-destroyer', '501st-legion', 'jedi-generals']),
    ('galactic-republic', 'navy', 'coruscant-home-defense-fleet', 'Coruscant Home Defense Fleet', 'Task force', 'Defense fleet', "Coruscant's home defense fleet guarded the galactic capital with Venators, gun platforms, and rapid-response starfighter wings during Separatist terror raids. The Battle of Coruscant saw this fleet clash with Grievous' largest armada in the war's climax. Senate Commandos and clone garrisons coordinated with naval units for planetary defense.", '#0369a1', ['venator-class-star-destroyer', 'senate-commando-guard', 'v-wing-starfighter-wing']),
    ('galactic-republic', 'navy', 'kashyyyk-defense-fleet', 'Kashyyyk Orbital Defense Fleet', 'Task force', 'Defense fleet', "Republic naval elements above Kashyyyk coordinated orbital bombardment support with Wookiee ground defenses and the 41st Elite Corps during the Separatist invasion. Star Destroyers and frigates interdicted Separatist landing craft while clone troopers fought in the treetops below. The fleet's actions preserved Wookiee cities until Order 66 fractured the alliance.", '#0ea5e9', ['wookiee-warriors', '41st-elite-corps', 'pelta-class-frigate-group']),
    ('galactic-republic', 'navy', 'hardcell-class-republic-transport', 'Republic Logistics Transport Group', 'Support ship', 'Transport', 'Republic logistics groups moved spare parts, rations, and munitions to forward staging areas using converted transports and Pelta support ships. Clone engineer corps depended on these convoys to maintain AT-TE battalions and gunship wings. Separatist raiders targeted them relentlessly along Mid Rim hyperspace routes.', '#38bdf8', ['clone-engineer-corps', 'pelta-class-frigate-group', 'consular-class-cruiser-escort']),
    ('galactic-republic', 'navy', 'light-cruiser-patrol-squadron', 'Arquitens-class Light Cruiser Squadron', 'Escort ship', 'Cruiser', 'Arquitens-class light cruisers screened Venator battle groups and pursued Separatist frigates through asteroid fields and nebulae. Their versatile hulls balanced speed with enough firepower to handle Recusant destroyers. These cruisers remained staples of Republic and later Imperial patrol doctrine.', '#2563eb', ['venator-class-star-destroyer', 'republic-venator-battle-group', 'v-wing-starfighter-wing']),
    ('galactic-empire', 'army', 'stormtrooper-corps', 'Stormtrooper Corps', 'Infantry', None, "White-armored stormtroopers became the face of Imperial occupation, enforcing Palpatine's rule from Coruscant to the Outer Rim with E-11 blasters and brutal efficiency. Recruited from across the Empire after the clone template program ended, they garrisoned worlds, conducted raids, and served aboard Star Destroyers. Their uniformity symbolized the Empire's demand for absolute conformity.", '#9ca3af', ['501st-legion', 'imperial-army', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'army', 'death-troopers', 'Death Troopers', 'Special forces', None, 'Death troopers in black plastoid armor guarded classified projects including the Death Star, Scarif data vaults, and Tarkin Initiative research sites. Enhanced with cybernetic augmentations and encrypted comms, they eliminated witnesses and protected high-value Imperial secrets. Their distorted voices and red sensor glow became nightmares for Rebel intelligence.', '#374151', ['imperial-intelligence-detachment', 'royal-guard', 'imperial-ii-class-star-destroyer']),
    ('galactic-empire', 'army', 'scout-troopers', 'Scout Troopers', 'Reconnaissance', None, 'Scout troopers mounted 74-Z speeder bikes for rapid reconnaissance on forest moons like Endor and frontier worlds across the Outer Rim. Their lighter armor traded protection for mobility and marksmanship at range. Scout trooper corps screened AT-ST advances and hunted Rebel patrols.', '#6b7280', ['shoretroopers', 'at-st-scout-company', 'imperial-garrison-legion']),
    ('galactic-empire', 'army', 'shoretroopers', 'Coastal Defender Stormtroopers', 'Environment specialist', None, "Shoretroopers—coastal defender stormtroopers—garrisoned Scarif's Citadel and other tropical Imperial installations with specialized helmets and pauldrons denoting rank. They coordinated with death troopers during the Battle of Scarif. Their tan armor suited beach and island fortress environments.", '#78716c', ['death-troopers', 'imperial-army', 'scarif-orbital-defense-group']),
    ('galactic-empire', 'army', 'snowtroopers', 'Cold Assault Stormtroopers', 'Environment specialist', None, "Snowtroopers in insulated armor assaulted Hoth's Echo Base and garrisoned ice worlds with heating packs and white camouflage. Cold assault platoons accompanied AT-AT walker battalions during the Empire's most famous ground victory. Their gear allowed extended operations in blizzards that disabled standard troopers.", '#d1d5db', ['at-at-walker-battalion', 'imperial-army', 'death-squadron']),
    ('galactic-empire', 'army', 'sandtroopers', 'Sandtroopers', 'Environment specialist', None, "Sandtroopers patrolled Tatooine's dunes searching for Rebel droids and enforcing Imperial law on desert worlds. Orange shoulder pauldrons marked squad leaders who coordinated dewback-mounted patrols across vast territories. Their survival gear included reinforced filters against sandstorms.", '#a8a29e', ['scout-troopers', 'imperial-garrison-legion', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'army', 'jumptroopers', 'Jumptroopers', 'Airborne', None, 'Jumptroopers used jetpacks to assault elevated positions, board vessels, and pursue fleeing Rebel soldiers over urban battlefields. Imperial airborne units deployed from Star Destroyer drop ships during planetary invasions. Their agility countered Rebel guerrilla tactics on rooftops and cliff fortresses.', '#71717a', ['stormtrooper-corps', 'at-st-scout-company', 'tie-defender-squadron']),
    ('galactic-empire', 'army', 'range-troopers', 'Range Troopers', 'Special forces', None, "Range troopers guarded Imperial cargo trains on Vandor and other frontier routes with magnetized armor and heavy blaster rifles. Their fur-lined gear resisted extreme cold while magnetic boots kept them aboard speeding conveyex cars. Range trooper squads represented the Empire's willingness to deploy elite troops for logistics security.", '#52525b', ['death-troopers', 'imperial-army', 'gozanti-class-cruiser-group']),
    ('galactic-empire', 'army', 'purge-troopers', 'Purge Troopers', 'Special forces', None, 'Purge troopers hunted surviving Jedi after Order 66 with electrostaffs, shielded tactics, and clone-era training adapted to Imperial service. Deployed on Kashyyyk, Nur, and other Jedi sighting hotspots, they worked alongside Inquisitors. Their dark armor and aggressive close combat made them feared Jedi killers.', '#374151', ['death-troopers', '501st-legion', 'inquisitorius-task-force']),
    ('galactic-empire', 'army', '501st-legion', '501st Legion', 'Legion', None, "Vader's Fist—the 501st Legion—carried blue-trimmed stormtrooper armor into the Empire's most sensitive operations from Hoth to Endor. The legion assaulted the Tantive IV, occupied Cloud City, and defended Death Star installations. Their combat record made them the premier Imperial stormtrooper unit.", '#64748b', ['stormtrooper-corps', 'death-troopers', 'death-squadron']),
    ('galactic-empire', 'army', 'royal-guard', "Emperor's Royal Guard", 'Bodyguard', None, "Crimson-robed Royal Guards protected Emperor Palpatine with force pikes and concealed blasters, selected from the Empire's most deadly soldiers. They stood silent in throne rooms and accompanied Palpatine to Death Star inspections and battle stations. Their presence signaled the Emperor's personal authority.", '#dc2626', ['death-troopers', 'imperial-intelligence-detachment', 'executor-class-super-star-destroyer']),
    ('galactic-empire', 'army', 'imperial-army', 'Imperial Army', 'Ground forces', None, "The Imperial Army combined stormtrooper garrisons with AT-AT walkers, AT-ST scouts, and occupation battalions to hold conquered worlds. Army commanders coordinated with the Imperial Navy for planetary invasions and punitive pacification campaigns. Unlike the Navy's officer corps, Army leadership drew from regional academies across the Core and Colonies.", '#71717a', ['at-at-walker-battalion', 'stormtrooper-corps', 'imperial-garrison-legion']),
    ('galactic-empire', 'army', 'at-at-walker-battalion', 'AT-AT Walker Battalion', 'Heavy armor', None, "All Terrain Armored Transport walkers towered over battlefields on Hoth and dozens of worlds, delivering crushing firepower with chin-mounted lasers and mass-driver cannons. Battalions advanced in staggered lines while snowtroopers and stormtroopers secured objectives behind them. AT-ATs embodied the Empire's preference for terror through overwhelming mechanized force.", '#52525b', ['at-st-scout-company', 'snowtroopers', 'imperial-army']),
    ('galactic-empire', 'army', 'at-st-scout-company', 'AT-ST Scout Company', 'Scout armor', None, 'All Terrain Scout Transport walkers screened flanks, pursued infantry, and provided fire support in forests and urban canyons where AT-ATs could not maneuver. Scout companies on Endor initially dominated Rebel forces before Ewok traps turned the battle. Their chicken-like gait became iconic in Imperial ground doctrine.', '#6b7280', ['at-at-walker-battalion', 'scout-troopers', 'imperial-garrison-legion']),
    ('galactic-empire', 'army', 'imperial-garrison-legion', 'Imperial Garrison Legion', 'Occupation force', None, 'Garrison legions maintained order on pacified worlds with barracks, detention centers, and orbital communication links to regional Moffs. These units mixed stormtroopers, Army personnel, and support droids to suppress dissent. Rebel cells targeted garrison legions as symbols of Imperial oppression.', '#78716c', ['stormtrooper-corps', 'imperial-army', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'army', 'imperial-shock-troopers', 'Imperial Shock Troopers', 'Assault', None, "Red-armored shock troopers served as Coruscant's elite enforcement branch before transitioning into security roles across Imperial City. They carried heavy rifles and riot gear for urban pacification and VIP protection. Shock trooper units bridged police and military functions on the capital.", '#991b1b', ['royal-guard', 'stormtrooper-corps', 'coruscant-defense-fleet']),
    ('galactic-empire', 'army', 'imperial-intelligence-detachment', 'Imperial Intelligence Detachment', 'Intelligence', None, 'Imperial Intelligence detachments coordinated with death troopers and ISB agents to eliminate Rebel networks, monitor Moff loyalty, and conduct counterespionage. Field detachments operated covertly while naval intelligence sections fed data to Star Destroyer task forces. Their work rarely appeared in public propaganda but shaped campaign planning.', '#374151', ['death-troopers', 'royal-guard', 'interdictor-class-cruiser']),
    ('galactic-empire', 'army', 'comp-force-assault-battalion', 'CompForce Assault Battalion', 'Mechanized infantry', None, 'CompForce assault battalions combined stormtroopers with repulsor tanks and artillery for rapid planetary suppression missions. These units spearheaded invasions when diplomacy failed and the Death Star was unavailable. CompForce doctrine emphasized combined arms over pure infantry waves.', '#64748b', ['imperial-army', 'at-at-walker-battalion', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'navy', 'imperial-i-class-star-destroyer', 'Imperial I-class Star Destroyer', 'Capital ship', 'Star Destroyer', "Imperial I-class Star Destroyers like Devastator became symbols of Imperial might with dagger profiles, turbolaser batteries, and TIE fighter complements numbering in the dozens. These vessels blockaded worlds, hunted Rebel convoys, and served as mobile command centers for Moffs and admirals. Their opening shot on the Tantive IV defined the Galactic Civil War's tone.", '#64748b', ['imperial-ii-class-star-destroyer', 'tie-fighter-wing', 'death-squadron']),
    ('galactic-empire', 'navy', 'imperial-ii-class-star-destroyer', 'Imperial II-class Star Destroyer', 'Capital ship', 'Star Destroyer', 'Imperial II-class Star Destroyers upgraded firepower and command systems, serving as fleet anchors at Hoth, Endor, and major Imperial staging areas. Avenger and other II-class hulls led Death Squadron elements under Darth Vader. Their increased reactor output supported heavier turbolaser cycling in sustained fleet actions.', '#52525b', ['imperial-i-class-star-destroyer', 'executor-class-super-star-destroyer', 'tie-interceptor-squadron']),
    ('galactic-empire', 'navy', 'executor-class-super-star-destroyer', 'Executor-class Super Star Destroyer', 'Capital ship', 'Dreadnought', "The Executor-class Super Star Destroyer Executor served as Darth Vader's flagship—a nineteen-kilometer dagger wielding thousands of weapons and a massive TIE complement. Super Star Destroyers projected terror beyond conventional fleet doctrine, capable of besieging entire star systems alone. The Executor's destruction at Endor marked a turning point in the Galactic Civil War.", '#374151', ['death-squadron', 'imperial-ii-class-star-destroyer', 'tie-advanced-squadron']),
    ('galactic-empire', 'navy', 'interdictor-class-cruiser', 'Interdictor-class Cruiser', 'Support ship', 'Interdictor', 'Interdictor cruisers generated gravity well projectors to pull ships from hyperspace, enabling ambushes against Rebel convoys and smuggler routes. Imperial Interdictors coordinated with Star Destroyer groups at battles like Bilbringi and numerous Outer Rim intercepts. Their distinctive dome arrays made them priority Rebel kill targets.', '#6b7280', ['imperial-i-class-star-destroyer', 'imperial-intelligence-detachment', 'raider-class-corvette-squadron']),
    ('galactic-empire', 'navy', 'arquitens-class-light-cruiser', 'Arquitens-class Light Cruiser', 'Escort ship', 'Cruiser', 'Arquitens-class light cruisers escorted convoys, supported Star Destroyer patrols, and engaged Rebel corvettes in tight skirmishes. Their versatile hulls served the Empire from Scarif to Lothal and beyond in both fleet and system defense roles. Light cruisers often carried TIE fighter squadrons for extended patrols.', '#78716c', ['imperial-i-class-star-destroyer', 'tie-fighter-wing', 'gozanti-class-cruiser-group']),
    ('galactic-empire', 'navy', 'raider-class-corvette-squadron', 'Raider-class Corvette Squadron', 'Escort ship', 'Corvette', 'Raider-class corvettes hunted Rebel starfighters and escorted priority convoys with anti-fighter batteries and tight maneuverability. Squadrons operated in Outer Rim sectors where larger Star Destroyers could not patrol efficiently. Raiders complemented Interdictor ambush tactics.', '#71717a', ['interdictor-class-cruiser', 'tie-interceptor-squadron', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'navy', 'gozanti-class-cruiser-group', 'Gozanti-class Cruiser Group', 'Support ship', 'Transport', 'Gozanti-class cruisers transported TIE fighters externally and moved supplies between garrison worlds with minimal escort requirements. Cruiser groups kept remote Imperial outposts armed during long Galactic Civil War sieges. Rebels frequently captured Gozantis to supplement their own logistics.', '#9ca3af', ['range-troopers', 'arquitens-class-light-cruiser', 'imperial-garrison-legion']),
    ('galactic-empire', 'navy', 'tie-fighter-wing', 'TIE Fighter Wing', 'Starfighter unit', 'Starfighter wing', 'TIE/ln space superiority fighters launched in swarms from Star Destroyer hangars, relying on numbers and Imperial pilot conditioning to overwhelm Rebel squadrons. TIE wings defined Imperial starfighter doctrine with no shields and maximum offensive output. Their screaming engines announced Imperial fleet arrivals across the galaxy.', '#64748b', ['tie-interceptor-squadron', 'tie-bomber-wing', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'navy', 'tie-interceptor-squadron', 'TIE Interceptor Squadron', 'Starfighter unit', 'Starfighter wing', "TIE/in interceptors with dagger-wing designs hunted Rebel X-wings and A-wings with superior speed and twin laser cannons. Interceptor squadrons screened Star Destroyers and pursued fleeing convoy escorts through asteroid fields. They represented the Empire's answer to improving Rebel starfighter performance.", '#52525b', ['tie-fighter-wing', 'tie-defender-squadron', 'imperial-ii-class-star-destroyer']),
    ('galactic-empire', 'navy', 'tie-bomber-wing', 'TIE Bomber Wing', 'Starfighter unit', 'Bomber wing', 'TIE/sa bombers delivered proton torpedoes and ordnance against Rebel bases, capital ships, and ground installations throughout the Galactic Civil War. Bomber wings supported ground assaults on Hoth and attempted to destroy fleeing transports. Their dual-hull design carried enough payload to threaten Mon Calamari cruisers.', '#6b7280', ['tie-fighter-wing', 'at-at-walker-battalion', 'death-squadron']),
    ('galactic-empire', 'navy', 'tie-defender-squadron', 'TIE Defender Squadron', 'Starfighter unit', 'Starfighter wing', "TIE/d Defenders combined shields, hyperdrives, and tri-wing agility into the Empire's most advanced starfighter—deployed in limited numbers against Rebel and rogue Imperial threats. Defender squadrons tested at Lothal and other secret facilities represented a technological edge Palpatine hoarded carefully. Their hexagonal wings distinguished them from standard TIEs.", '#374151', ['tie-interceptor-squadron', 'jumptroopers', 'inquisitorius-task-force']),
    ('galactic-empire', 'navy', 'death-squadron', 'Death Squadron', 'Task force', 'Task force', "Death Squadron under Darth Vader combined the Executor, Imperial II-class Star Destroyers, and elite TIE wings to hunt the Rebel Alliance across the Outer Rim. The squadron blockaded Hoth and nearly captured Luke Skywalker multiple times. Its concentration of firepower made it the Empire's premier anti-Rebel task force.", '#52525b', ['executor-class-super-star-destroyer', '501st-legion', 'snowtroopers']),
    ('galactic-empire', 'navy', 'scarif-orbital-defense-group', 'Scarif Orbital Shield Defense Group', 'Task force', 'Defense fleet', "Scarif's orbital defense combined shield gate stations, turbolaser platforms, and shoretrooper garrisons to protect the Citadel's Death Star plans archive. The Battle of Scarif tested this group's ability to stop a concentrated Rebel raid. Death troopers and Star Destroyer reinforcements ultimately responded to the breach.", '#78716c', ['shoretroopers', 'death-troopers', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'navy', 'coruscant-defense-fleet', 'Coruscant System Defense Fleet', 'Task force', 'Defense fleet', "Coruscant's system defense fleet maintained peace in the Imperial capital with Star Destroyers, patrol craft, and shock trooper security detachments on orbital stations. While rarely tested in full fleet actions after the Clone Wars, it represented the Empire's political center of gravity. Any threat to Coruscant triggered immediate overwhelming response.", '#71717a', ['imperial-shock-troopers', 'royal-guard', 'imperial-i-class-star-destroyer']),
    ('galactic-empire', 'navy', 'inquisitorius-task-force', 'Inquisitorius Task Force', 'Task force', 'Task force', 'Inquisitorius task forces paired Purge Troopers, TIE Defenders, and Interdictor support to hunt Jedi survivors and Force-sensitive children. These mobile groups operated from secret bases with direct reporting lines to Vader and Palpatine. Their missions rarely appeared in Imperial public records.', '#374151', ['purge-troopers', 'tie-defender-squadron', 'interdictor-class-cruiser']),
    ('rebel-alliance', 'army', 'rebel-troopers', 'Rebel Troopers', 'Infantry', None, "Rebel troopers in olive drab field gear formed the Alliance's ground backbone—volunteers, deserters, and planetary militias united against Imperial occupation. They fought with DH-17 blasters, homemade fortifications, and stubborn morale from Hoth to Endor. Every trooper represented a world that refused Palpatine's New Order.", '#e85d04', ['rebel-pathfinders', 'massassi-group', 'home-one-fleet-group']),
    ('rebel-alliance', 'army', 'rebel-pathfinders', 'Rebel Pathfinders', 'Special forces', None, 'Rebel pathfinders led assault landings on Scarif and Endor with satchel charges, grappling gear, and camouflaged armor for breaching Imperial bunkers. These special forces teams opened holes in shield generators and detention blocks before main infantry waves arrived. Pathfinder doctrine prioritized speed, stealth, and explosive entry.', '#ea580c', ['rebel-troopers', 'rogue-squadron', 'battle-of-scarif-task-group']),
    ('rebel-alliance', 'army', 'rebel-commandos', 'Rebel Commando Teams', 'Special forces', None, 'Rebel commando teams conducted sabotage, prisoner extraction, and assassination missions against Imperial governors and garrison commanders. Trained on Yavin and scattered safe houses, they operated in cells too small for the Empire to easily detect. Commando raids kept Imperial forces off-balance between major fleet engagements.', '#c2410c', ['rebel-pathfinders', 'massassi-group', 'endor-strike-team']),
    ('rebel-alliance', 'army', 'massassi-group', 'Massassi Group', 'Command', None, "The Massassi Group coordinated Rebel operations from Yavin 4's Great Temple, planning the Death Star assault and broader Galactic Civil War strategy. Named for the Massassi warriors who once inhabited the moon, the group linked scattered cells into a coherent military force. Its command staff worked directly with Mon Mothma and General Dodonna.", '#fb923c', ['rebel-troopers', 'rogue-squadron', 'home-one-fleet-group']),
    ('rebel-alliance', 'army', 'endor-strike-team', 'Endor Strike Team', 'Special operations', None, "The Endor strike team under Han Solo infiltrated the forest moon to destroy the shield generator protecting the second Death Star. Mixed pathfinders, commandos, and volunteers fought alongside Ewok allies against scout troopers and AT-STs. Their success enabled the Rebel fleet's survival in the decisive space battle above.", '#f97316', ['rebel-pathfinders', 'rebel-commandos', 'rebel-fleet-command']),
    ('rebel-alliance', 'army', 'hoth-defense-garrison', 'Hoth Defense Garrison', 'Garrison', None, "Echo Base's Hoth garrison held the icy world long enough for key Rebel leaders to escape the Imperial assault in the Battle of Hoth. Snow-suited troopers, ion cannons, and snowspeeder support delayed AT-AT advances despite overwhelming odds. The garrison's sacrifice bought time for the Alliance's survival.", '#ea580c', ['rebel-troopers', 'snowspeeder-wing', 'rogue-squadron']),
    ('rebel-alliance', 'army', 'alderaanian-survivor-militia', 'Alderaanian Survivor Militia', 'Allied infantry', None, "Survivors of Alderaan's destruction rallied into militia units serving the Alliance with fierce motivation and diplomatic connections across the Core. Alderaanian soldiers brought training, intelligence networks, and moral authority to Rebel operations. Their presence reminded the galaxy what the Empire had destroyed.", '#e85d04', ['rebel-troopers', 'massassi-group', 'mon-calamari-cruiser-group']),
    ('rebel-alliance', 'army', 'sullustan-assault-battalion', 'Sullustan Assault Battalion', 'Allied infantry', None, "Sullustan soldiers contributed expertise in underground warfare and industrial sabotage during the liberation of their homeworld and subsequent Alliance campaigns. Their battalions coordinated with Nien Nunb and Sullustan pilots for combined arms operations. Sullust's liberation opened critical shipyard routes for the Rebel fleet.", '#c2410c', ['rebel-troopers', 'rebel-pathfinders', 'liberation-of-sullust-group']),
    ('rebel-alliance', 'army', 'bothan-intelligence-infantry', 'Bothan Intelligence Infantry', 'Intelligence', None, "Bothan spies and supporting infantry sacrificed heavily to deliver Death Star II plans to the Alliance before the Battle of Endor. Their intelligence corps worked alongside combat teams to infiltrate Imperial data networks and physical archives. Many Bothans died so the Alliance could strike at the Emperor's trap.", '#fb923c', ['massassi-group', 'rebel-commandos', 'endor-fleet-battle-group']),
    ('rebel-alliance', 'army', 'rebel-artillery-battery', 'Rebel Artillery Battery', 'Artillery', None, 'Rebel artillery batteries deployed DF.9 turrets, proton mortars, and captured Imperial ordnance to support entrenched positions on Hoth, Atollon, and dozens of hidden bases. Artillery crews bought time for evacuations against Imperial armor advances. Their camouflaged emplacements punished overconfident Imperial ground assaults.', '#ea580c', ['hoth-defense-garrison', 'rebel-troopers', 'rebel-transport-convoy']),
    ('rebel-alliance', 'army', 'rebel-speeder-corps', 'Rebel Speeder Corps', 'Reconnaissance', None, "Rebel speeder corps operated swoops, landspeeders, and modified repulsorcraft for scouting, convoy harassment, and rapid flanking on worlds with limited starfighter support. Speeder units on Tatooine and Jedha harassed Imperial patrols and smuggled supplies. Their mobility compensated for the Alliance's often inferior heavy armor.", '#f97316', ['rebel-troopers', 'rebel-pathfinders', 'corellian-corvette-squadron']),
    ('rebel-alliance', 'army', 'rebel-medical-corps', 'Rebel Medical Corps', 'Support', None, 'Rebel medical corps personnel evacuated wounded from battlefields under fire, operating field hospitals on ships like the Liberty and hidden bases across the Outer Rim. Medics treated alien and human soldiers alike with limited supplies and constant Imperial pursuit. Their work preserved experienced pilots and soldiers for critical campaigns.', '#e85d04', ['rebel-troopers', 'pelta-class-rebel-support', 'home-one-fleet-group']),
    ('rebel-alliance', 'army', 'rebel-engineer-battalion', 'Rebel Engineer Battalion', 'Combat engineers', None, "Rebel engineers maintained starfighter readiness, repaired shield generators, and constructed hidden base infrastructure on Yavin, Hoth, and D'Qar predecessors. Engineer battalions worked in secrecy with limited parts, improvising solutions that kept the fleet operational. Scarif and Endor successes depended on their explosive breaching skills.", '#c2410c', ['rebel-pathfinders', 'rebel-artillery-battery', 'nebulon-b-frigate-group']),
    ('rebel-alliance', 'army', 'rebel-desert-infantry', 'Rebel Desert Infantry', 'Environment specialist', None, 'Desert infantry adapted Alliance field gear for Tatooine, Jedha, and arid Outer Rim worlds where Imperial garrisons relied on sandtrooper patrols. These units used cloaks, moisture gear, and local guides to ambush convoys and rescue prisoners. Desert cells kept the Rebellion alive where fleet support could not reach.', '#fb923c', ['rebel-speeder-corps', 'rebel-troopers', 'corellian-corvette-squadron']),
    ('rebel-alliance', 'army', 'rebel-specforce-marine-regiment', 'Rebel SpecForce Marine Regiment', 'Marines', None, 'Rebel SpecForce marines boarded Imperial vessels, secured landing zones, and conducted zero-gravity assaults alongside naval operations. Marine regiments trained for the brutal close combat of corridor fighting aboard Star Destroyers and orbital stations. Their operations complemented starfighter strikes in combined fleet assaults.', '#ea580c', ['rebel-commandos', 'rebel-specforce-pathfinder-company', 'mon-calamari-cruiser-group']),
    ('rebel-alliance', 'army', 'rebel-specforce-pathfinder-company', 'Rebel SpecForce Pathfinder Company', 'Special forces', None, 'SpecForce pathfinder companies specialized in long-range reconnaissance and covert insertion ahead of major Alliance offensives. They marked landing zones, sabotaged communications, and reported Imperial troop movements from behind enemy lines. Pathfinder companies fed intelligence directly to Massassi Group planners.', '#f97316', ['rebel-pathfinders', 'rebel-specforce-marine-regiment', 'massassi-group']),
    ('rebel-alliance', 'army', 'rebel-training-corps', 'Rebel Training Corps', 'Training command', None, 'The Rebel training corps converted farmers, miners, and deserters into disciplined soldiers at hidden camps across the galaxy. Instructors from Alderaan, Chandrila, and Mon Calamari standardized tactics despite scarce resources. Training corps graduates filled the ranks depleted by Hoth and earlier Imperial victories.', '#e85d04', ['rebel-troopers', 'massassi-group', 'rebel-medical-corps']),
    ('rebel-alliance', 'navy', 'home-one-fleet-group', 'Home One Fleet Group', 'Task force', 'Flagship', "Admiral Ackbar's Home One fleet group served as the Alliance's primary command formation, coordinating Mon Calamari cruisers and starfighter wings at Endor and other decisive battles. Home One's bridge hosted the strategic mind that warned against Imperial traps. The fleet group embodied Mon Calamari shipbuilding genius.", '#f97316', ['mon-calamari-cruiser-group', 'rogue-squadron', 'massassi-group']),
    ('rebel-alliance', 'navy', 'mon-calamari-cruiser-group', 'Mon Calamari Star Cruiser Group', 'Capital ship', 'Cruiser', 'Mon Calamari star cruisers—Home One, Liberty, and dozens more—provided the Alliance with capital ships capable of matching Imperial Star Destroyers. Their organic hull designs and redundant systems survived punishment that would destroy lesser vessels. Mon Calamari engineers converted passenger liners into warships in secret shipyards.', '#fb923c', ['home-one-fleet-group', 'nebulon-b-frigate-group', 'a-wing-interceptor-wing']),
    ('rebel-alliance', 'navy', 'nebulon-b-frigate-group', 'Nebulon-B Frigate Group', 'Escort ship', 'Frigate', 'Nebulon-B escort frigates like the Redemption served as medical ships, fighter tenders, and convoy escorts throughout the Galactic Civil War. Frigate groups kept Alliance supply lines alive between major fleet concentrations. Their elongated hulls became iconic in Rebel propaganda holos.', '#ea580c', ['mon-calamari-cruiser-group', 'rebel-medical-corps', 'x-wing-starfighter-wing']),
    ('rebel-alliance', 'navy', 'corellian-corvette-squadron', 'CR90 Corellian Corvette Squadron', 'Escort ship', 'Corvette', 'CR90 corvettes like Tantive IV and blockade runners delivered diplomats, supplies, and stolen Death Star plans while outrunning Imperial Star Destroyers. Corvette squadrons screened larger cruisers and inserted commando teams on covert missions. Their speed made them indispensable Rebel assets.', '#e85d04', ['rebel-speeder-corps', 'rebel-desert-infantry', 'rebel-transport-convoy']),
    ('rebel-alliance', 'navy', 'x-wing-starfighter-wing', 'X-wing Starfighter Wing', 'Starfighter unit', 'Starfighter wing', "T-65B X-wing starfighters served as the Alliance's primary space superiority platform, flown by aces like Luke Skywalker, Wedge Antilles, and Poe Dameron's predecessors. X-wing wings destroyed Death Stars, escorted convoys, and defended Mon Calamari cruisers in fleet actions. Their S-foil configuration became the Rebellion's symbol.", '#fb923c', ['rogue-squadron', 'y-wing-bomber-wing-rebel', 'mon-calamari-cruiser-group']),
    ('rebel-alliance', 'navy', 'rogue-squadron', 'Rogue Squadron', 'Starfighter unit', 'Starfighter wing', "Rogue Squadron under Wedge Antilles and previously Luke Skywalker represented the Alliance's elite X-wing unit, flying the Death Star trench run and countless fleet engagements. Rogues specialized in precision strikes against Imperial superweapons and ace TIE pilots. Their name carried morale weight across the Rebellion.", '#f97316', ['x-wing-starfighter-wing', 'massassi-group', 'home-one-fleet-group']),
    ('rebel-alliance', 'navy', 'y-wing-bomber-wing-rebel', 'Y-wing Bomber Wing', 'Starfighter unit', 'Bomber wing', "Rebel Y-wing bombers delivered ion torpedoes and proton ordnance against Imperial Star Destroyers, shield generators, and ground installations from Scarif to Endor. Gold Squadron's Y-wings struck the first Death Star trench before X-wings finished the run. Bomber wings absorbed heavy casualties to open holes in Imperial defenses.", '#ea580c', ['x-wing-starfighter-wing', 'rebel-artillery-battery', 'battle-of-scarif-task-group']),
    ('rebel-alliance', 'navy', 'a-wing-interceptor-wing', 'A-wing Interceptor Wing', 'Starfighter unit', 'Starfighter wing', "RZ-1 A-wing interceptors provided the Alliance with the fastest starfighters in the fleet, hunting TIE interceptors and screening Mon Calamari cruisers during fleet engagements. Arvel Crynyd's sacrifice against the Executor at Endor demonstrated their kamikaze potential. A-wing wings demanded pilots with razor reflexes.", '#c2410c', ['mon-calamari-cruiser-group', 'home-one-fleet-group', 'endor-fleet-battle-group']),
    ('rebel-alliance', 'navy', 'b-wing-assault-wing', 'B-wing Assault Wing', 'Starfighter unit', 'Starfighter wing', 'A/SF-01 B-wing assault fighters concentrated heavy firepower into a rotating cockpit design for anti-capital ship strikes. B-wing wings targeted Imperial Star Destroyer bridge towers and shield domes in coordinated fleet assaults. Their unusual profile made them distinctive in Alliance hangar bays.', '#e85d04', ['y-wing-bomber-wing-rebel', 'mon-calamari-cruiser-group', 'rebel-specforce-marine-regiment']),
    ('rebel-alliance', 'navy', 'rebel-fleet-command', 'Rebel Alliance Fleet Command', 'Task force', 'Task force', 'Rebel Fleet Command under Admiral Ackbar integrated scattered task groups into coherent campaigns against Imperial staging areas and superweapons. Fleet Command coordinated intelligence from Bothan spies, Massassi Group planners, and sector cells into operational orders. Its success at Endor validated years of asymmetric buildup.', '#f97316', ['home-one-fleet-group', 'massassi-group', 'bothan-intelligence-infantry']),
    ('rebel-alliance', 'navy', 'battle-of-scarif-task-group', 'Scarif Raid Task Group', 'Task force', 'Task force', "The Scarif raid task group combined Profundity, corvettes, and starfighter wings in the Alliance's first open fleet action against an Imperial security world. Rogue One's ground team transmitted Death Star plans while the task group held off Star Destroyers long enough to pass the data to Leia Organa. The battle proved the Rebellion could strike Imperial installations directly.", '#fb923c', ['rebel-pathfinders', 'y-wing-bomber-wing-rebel', 'corellian-corvette-squadron']),
    ('rebel-alliance', 'navy', 'endor-fleet-battle-group', 'Endor Fleet Battle Group', 'Task force', 'Task force', "The Endor fleet battle group engaged the Imperial Navy above the forest moon while ground teams destroyed the shield generator. Ackbar's cruisers and starfighter wings survived Palpatine's trap through tactical discipline and Lando Calrissian's leadership on the Millennium Falcon. The battle group's victory ended the Emperor's reign.", '#ea580c', ['home-one-fleet-group', 'endor-strike-team', 'a-wing-interceptor-wing']),
    ('rebel-alliance', 'navy', 'rebel-transport-convoy', 'Rebel Transport Convoy', 'Support ship', 'Transport', 'Rebel transport convoys moved troops, fuel, and munitions between hidden bases under escort from corvettes and frigates. Imperial Interdictor ambushes made convoy duty among the most dangerous Rebel naval assignments. Successful convoys kept Hoth, Yavin, and post-Hoth remnants supplied against all odds.', '#e85d04', ['corellian-corvette-squadron', 'nebulon-b-frigate-group', 'rebel-artillery-battery']),
    ('rebel-alliance', 'navy', 'pelta-class-rebel-support', 'Rebel Pelta Support Group', 'Support ship', 'Frigate', 'Captured and donated Pelta-class support ships served Rebel fleets as hospital vessels and repair tenders during extended campaigns. Support groups kept X-wing and Y-wing squadrons operational between battles with limited spare parts. Medical Peltas treated casualties from Scarif through Endor.', '#c2410c', ['rebel-medical-corps', 'nebulon-b-frigate-group', 'home-one-fleet-group']),
    ('rebel-alliance', 'navy', 'liberation-of-sullust-group', 'Liberation of Sullust Task Group', 'Task force', 'Task force', "The Sullust liberation task group combined orbital strikes with Sullustan ground assault battalions to free the world from Imperial control. Success opened Sullustan shipyards and pilot cadres to the Alliance ahead of Endor. Nien Nunb's homeworld became a symbol of Rebel planetary liberation.", '#f97316', ['sullustan-assault-battalion', 'x-wing-starfighter-wing', 'rebel-fleet-command']),
    ('rebel-alliance', 'navy', 'snowspeeder-wing', 'T-47 Airspeeder Wing', 'Starfighter unit', 'Air support wing', "T-47 airspeeders on Hoth used tow cables in unconventional tactics against AT-AT walkers during Echo Base's evacuation. Though not true starfighters, the airspeeder wing represented planetary air support integrated with ground garrisons. Their harpoon tactics became legendary in Rebel training holos.", '#ea580c', ['hoth-defense-garrison', 'rogue-squadron', 'rebel-artillery-battery']),
    ('first-order', 'army', 'stormtrooper-corps', 'First Order Stormtroopers', 'Infantry', None, 'First Order stormtroopers were raised from childhood in batch training programs on undisclosed worlds, conditioned for absolute loyalty to Supreme Leader Snoke and later Kylo Ren. FN corps designations tracked units like FN-2187 before defection revealed cracks in the conditioning. White armor updated Imperial designs with improved seals and comm systems for modern warfare.', '#b91c1c', ['flametroopers', 'captain-phasma-guard', 'resurgent-class-star-destroyer']),
    ('first-order', 'army', 'flametroopers', 'First Order Flametroopers', 'Specialist', None, "Flametroopers wielded D-93 incinerator flamethrowers to clear trenches, forest entrenchments, and Resistance bunkers on Takodana and Starkiller Base approaches. Their bright armor markings identified specialist platoons attached to standard stormtrooper battalions. Flametroopers embodied the First Order's willingness to annihilate rather than capture.", '#991b1b', ['stormtrooper-corps', 'snowtroopers', 'resurgent-class-star-destroyer']),
    ('first-order', 'army', 'snowtroopers', 'First Order Snowtroopers', 'Environment specialist', None, "Snowtroopers garrisoned Starkiller Base's frozen surface and other cold-weather installations with insulated armor derived from Imperial cold assault designs. They patrolled superweapon trenches where thermal exhaust ports required constant security. Snowtrooper battalions reflected the First Order's revival of Imperial environment doctrine.", '#7f1d1d', ['stormtrooper-corps', 'flametroopers', 'starkiller-base-garrison']),
    ('first-order', 'army', 'riot-control-troopers', 'First Order Riot Control Troopers', 'Security', None, 'Riot control stormtroopers carried electrostaffs and non-lethal ordnance for crowd suppression on occupied worlds and aboard Star Destroyers. Their baton training focused on breaking civilian resistance without wasting blaster ammunition. RC units deployed when the First Order preferred visible intimidation over massacre.', '#dc2626', ['stormtrooper-corps', 'special-forces-troopers', 'finalizer-battle-group']),
    ('first-order', 'army', 'megablaster-heavy-troopers', 'Megablaster Heavy Troopers', 'Heavy infantry', None, "Heavy troopers carried FWMB-10 repeating blasters capable of suppressing Resistance infantry and light vehicles in sustained firefights. Megablaster squads anchored stormtrooper advance lines during assaults on Maz Kanata's castle and other targets. Their role mirrored Imperial heavy weapons platoons updated for First Order logistics.", '#ef4444', ['stormtrooper-corps', 'flametroopers', 'at-m6-walker-battalion']),
    ('first-order', 'army', 'special-forces-troopers', 'First Order Special Forces Troopers', 'Special forces', None, 'First Order special forces units operated with greater autonomy, camouflaged armor variants, and advanced reconnaissance gear for hunting Resistance cells. SF troopers pursued Poe Dameron on Jakku and conducted deep strikes beyond standard garrison deployments. Their training exceeded standard stormtrooper batch programs.', '#991b1b', ['stormtrooper-corps', 'knights-of-ren', 'tie-sf-squadron']),
    ('first-order', 'army', 'captain-phasma-guard', "Captain Phasma's Command Guard", 'Elite guard', None, "Captain Phasma's chrome-armored command guard enforced discipline among stormtrooper ranks with summary punishment and elite combat standards aboard the Finalizer. Phasma's polished armor became propaganda symbolizing First Order perfectionism. Her guard units accompanied high-profile invasions and training inspections.", '#e5e7eb', ['stormtrooper-corps', 'finalizer-battle-group', 'resurgent-class-star-destroyer']),
    ('first-order', 'army', 'knights-of-ren', 'Knights of Ren', 'Force order', None, "The Knights of Ren served Kylo Ren as dark side warriors hunting Jedi survivors and Force artifacts across the Unknown Regions and mapped galaxy. Their mismatched armor and brutal tactics filled the gap between Inquisitorius legacy and Sith apprenticeship. Ren's knights intimidated even First Order officers who distrusted Force users.", '#450a0a', ['special-forces-troopers', 'supreme-leader-guard', 'kylo-ren-command-group']),
    ('first-order', 'army', 'supreme-leader-guard', "Supreme Leader's Elite Praetorian Guard", 'Bodyguard', None, "Elite praetorian guards in crimson armor protected Supreme Leader Snoke aboard his flagship with melee weapons designed to counter Force users. Their synchronized combat forms tested Kylo Ren and Rey during the throne room confrontation. Praetorian guards represented the First Order's peak close-combat training.", '#7f1d1d', ['knights-of-ren', 'captain-phasma-guard', 'supremacy-flagship-group']),
    ('first-order', 'army', 'at-m6-walker-battalion', 'First Order AT-M6 Walker Battalion', 'Heavy armor', None, "All Terrain MegaCaliber Six walkers deployed on Crait with orbital bombardment-scale cannons designed to crack Resistance fortress lines. AT-M6 battalions represented the First Order's evolution beyond Imperial AT-AT designs with heavier firepower and longer legs. Their silhouettes dominated the salt plains assault.", '#b91c1c', ['at-hh-scout-walker-company', 'megablaster-heavy-troopers', 'crait-invasion-force']),
    ('first-order', 'army', 'at-hh-scout-walker-company', 'First Order AT-HH Scout Walker Company', 'Scout armor', None, 'All Terrain Heavy Hauler and lighter First Order scout walkers screened flanks during planetary invasions and guarded convoy routes on Jakku and other worlds. Scout companies coordinated with TIE fighter sweeps to eliminate Resistance spotters. Their deployment filled tactical gaps between infantry and mega-caliber walkers.', '#991b1b', ['at-m6-walker-battalion', 'stormtrooper-corps', 'first-order-transport-fleet']),
    ('first-order', 'army', 'first-order-security-bureau-infantry', 'First Order Security Bureau Infantry', 'Intelligence', None, "First Order Security Bureau infantry conducted arrests, interrogations, and counterintelligence operations on occupied worlds and within fleet ranks. FSIB teams hunted Resistance sympathizers and monitored stormtrooper loyalty after FN-2187's defection. Their black-uniformed agents bridged military and police functions.", '#450a0a', ['special-forces-troopers', 'stormtrooper-corps', 'interdictor-resurgent-group']),
    ('first-order', 'army', 'first-order-jumptroopers', 'First Order Jumptroopers', 'Airborne', None, 'First Order jumptroopers used jetpacks to assault elevated positions during urban invasions and boarding actions against Resistance vessels. Airborne platoons descended on Takodana and Starkiller approaches to encircle fleeing targets. Their tactics updated Imperial jumptrooper doctrine with improved thrust controls.', '#ef4444', ['stormtrooper-corps', 'special-forces-troopers', 'tie-silencer-squadron']),
    ('first-order', 'army', 'starkiller-base-garrison', 'Starkiller Base Garrison', 'Garrison', None, "Starkiller Base's garrison combined snowtroopers, technicians, and TIE wings to protect the planet-converted superweapon that destroyed the Hosnian system. Garrison command coordinated surface patrols with orbital defenses until Resistance sabotage triggered the base's collapse. The garrison's failure marked a catastrophic First Order intelligence breakdown.", '#7f1d1d', ['snowtroopers', 'stormtrooper-corps', 'starkiller-base-defense-fleet']),
    ('first-order', 'army', 'first-order-artillery-corps', 'First Order Artillery Corps', 'Artillery', None, 'First Order artillery corps deployed self-propelled cannons and orbital fire coordination teams during sieges of Resistance holdouts. Artillery units softened targets before AT-M6 advances on Crait and supported invasions of neutral worlds. Their fire direction centers linked ground units with Star Destroyer bombardment.', '#b91c1c', ['at-m6-walker-battalion', 'megablaster-heavy-troopers', 'resurgent-class-star-destroyer']),
    ('first-order', 'army', 'first-order-warlord-legion', 'First Order Warlord Legion', 'Legion', None, 'Warlord legions consolidated veteran stormtrooper battalions, walker companies, and special forces under regional commanders expanding First Order territory in the Unknown Regions and Outer Rim. These legions operated with greater autonomy than standard garrisons during the post-Starkiller consolidation period. Warlord commands reported ultimately to Supreme Leader authority.', '#991b1b', ['stormtrooper-corps', 'special-forces-troopers', 'first-order-expeditionary-fleet']),
    ('first-order', 'army', 'first-order-labor-corps', 'First Order Labor Corps', 'Support', None, 'First Order labor corps conscripted prisoners and conquered populations to build superweapons, Star Destroyers, and infrastructure across First Order space. Though not frontline combat units, labor corps supported military expansion with forced production that fed stormtrooper training and fleet construction. Resistance propaganda highlighted labor corps abuses to recruit allies.', '#7f1d1d', ['starkiller-base-garrison', 'first-order-security-bureau-infantry', 'first-order-transport-fleet']),
    ('first-order', 'navy', 'resurgent-class-star-destroyer', 'Resurgent-class Star Destroyer', 'Capital ship', 'Star Destroyer', "Resurgent-class Star Destroyers like the Finalizer dwarfed Imperial predecessors, carrying hundreds of TIE fighters and thousands of stormtroopers for planetary invasions. These dagger hulls projected First Order power at Jakku, Takodana, and across the Unknown Regions expansion. Resurgent-class vessels symbolized the regime's military revival.", '#ef4444', ['finalizer-battle-group', 'tie-fo-fighter-wing', 'first-order-expeditionary-fleet']),
    ('first-order', 'navy', 'mandator-iv-class-siege-dreadnought', 'Mandator IV-class Siege Dreadnought', 'Capital ship', 'Dreadnought', 'Mandator IV-class siege dreadnoughts like the Fulminatrix carried orbital autocannons capable of glassing planetary surfaces from orbit. Siege dreadnoughts supported First Order terror campaigns against worlds harboring Resistance sympathizers. Their massive guns made them priority targets for Resistance bomber wings.', '#b91c1c', ['resurgent-class-star-destroyer', 'tie-bomber-wing-fo', 'hosnian-cataclysm-group']),
    ('first-order', 'navy', 'tie-fo-fighter-wing', 'TIE/fo Space Superiority Fighter Wing', 'Starfighter unit', 'Starfighter wing', 'TIE/fo fighters updated Imperial designs with improved sensors and weapons for First Order fleet defense and planetary assault screens. Fighter wings launched from Resurgent-class hangars in overwhelming numbers during Jakku and Takodana operations. Their red sensor glow distinguished them from Imperial predecessors.', '#991b1b', ['tie-sf-squadron', 'tie-bomber-wing-fo', 'resurgent-class-star-destroyer']),
    ('first-order', 'navy', 'tie-sf-squadron', 'TIE/sf Special Forces Fighter Squadron', 'Starfighter unit', 'Starfighter wing', 'TIE/sf fighters added rear gunners and enhanced systems for special forces operations requiring independent hyperspace-capable starfighter support. SF squadrons escorted infiltration drops and hunted Resistance pilots like Poe Dameron. Their two-seat configuration improved survivability against ace opponents.', '#7f1d1d', ['special-forces-troopers', 'tie-fo-fighter-wing', 'finalizer-battle-group']),
    ('first-order', 'navy', 'tie-bomber-wing-fo', 'First Order TIE Bomber Wing', 'Starfighter unit', 'Bomber wing', "First Order TIE bombers delivered ordnance against Resistance bases and planetary fortifications during siege operations coordinated with Mandator IV dreadnoughts. Bomber wings attempted to destroy Resistance transports fleeing D'Qar and other hidden locations. Heavy payloads compensated for slower maneuverability.", '#dc2626', ['tie-fo-fighter-wing', 'mandator-iv-class-siege-dreadnought', 'first-order-artillery-corps']),
    ('first-order', 'navy', 'tie-silencer-squadron', 'TIE/vn Silencer Squadron', 'Starfighter unit', 'Starfighter wing', "Kylo Ren's TIE Silencer prototypes and limited production models combined speed, shields, and heavy weapons for elite pilot operations. Silencer squadrons tested technology later adapted for wider First Order starfighter upgrades. Ren personally flew Silencers in pursuit of Resistance leaders.", '#450a0a', ['knights-of-ren', 'first-order-jumptroopers', 'kylo-ren-command-group']),
    ('first-order', 'navy', 'first-order-transport-fleet', 'First Order Transport Fleet', 'Support ship', 'Transport', 'First Order transport fleets moved stormtrooper divisions, walker battalions, and labor corps between Unknown Regions shipyards and invasion targets. AT-HH companies and garrison units depended on these convoys for rapid deployment. Resistance convoy raiding targeted transports to delay First Order expansion.', '#991b1b', ['at-hh-scout-walker-company', 'first-order-labor-corps', 'resurgent-class-star-destroyer']),
    ('first-order', 'navy', 'finalizer-battle-group', 'Finalizer Battle Group', 'Task force', 'Flagship', "The Finalizer battle group under General Hux and Captain Phasma spearheaded First Order operations from Jakku reconnaissance through Starkiller Base's activation. Resurgent-class escorts and TIE wings made the group the regime's most visible military instrument. FN-2187's defection during the group's Jakku deployment exposed training flaws.", '#ef4444', ['resurgent-class-star-destroyer', 'captain-phasma-guard', 'tie-sf-squadron']),
    ('first-order', 'navy', 'supremacy-flagship-group', 'Supremacy Flagship Group', 'Task force', 'Flagship', "Supreme Leader Snoke's Supremacy served as a mobile capital—megaclass Star Dreadnought housing factories, training grounds, and the throne room where Kylo Ren killed Snoke. The flagship group carried TIE wings and fleet command authority across First Order space. Its destruction fragmented First Order naval coordination.", '#b91c1c', ['supreme-leader-guard', 'resurgent-class-star-destroyer', 'tie-silencer-squadron']),
    ('first-order', 'navy', 'starkiller-base-defense-fleet', 'Starkiller Base Defense Fleet', 'Task force', 'Defense fleet', "Starkiller Base's defense fleet combined Resurgent-class Star Destroyers and TIE wings to protect the superweapon during Hosnian Prime's destruction and subsequent Resistance infiltration. Orbital patrols failed to stop Han Solo's sabotage team despite surface garrison strength. The fleet's dispersal after the base's implosion weakened First Order territorial control.", '#7f1d1d', ['starkiller-base-garrison', 'snowtroopers', 'resurgent-class-star-destroyer']),
    ('first-order', 'navy', 'hosnian-cataclysm-group', 'Hosnian Cataclysm Strike Group', 'Task force', 'Task force', "The Hosnian cataclysm strike group positioned Starkiller Base and escort elements to destroy the New Republic Senate and fleet in a single superweapon volley. This operation decapitated New Republic leadership and triggered galactic war anew. The strike group's success was the First Order's greatest strategic victory.", '#991b1b', ['mandator-iv-class-siege-dreadnought', 'starkiller-base-defense-fleet', 'starkiller-base-garrison']),
    ('first-order', 'navy', 'crait-invasion-force', 'Crait Invasion Force', 'Task force', 'Task force', "The Crait invasion force combined AT-M6 walker battalions, TIE wings, and Resurgent-class fire support to destroy the Resistance's last visible redoubt in salt-crystal trenches. Orbital bombardment and mega-caliber walkers nearly ended the Resistance until Luke Skywalker's projection bought escape time. The force demonstrated First Order preference for overwhelming combined arms.", '#ef4444', ['at-m6-walker-battalion', 'first-order-artillery-corps', 'tie-fo-fighter-wing']),
    ('first-order', 'navy', 'first-order-expeditionary-fleet', 'First Order Expeditionary Fleet', 'Task force', 'Task force', "First Order expeditionary fleets expanded territory beyond former Imperial borders into the Unknown Regions with Resurgent-class hulls and warlord legions. Expeditionary doctrine prioritized permanent occupation over raiding. These fleets represented the long-term threat Mon Mothma's successors failed to fully suppress.", '#b91c1c', ['first-order-warlord-legion', 'resurgent-class-star-destroyer', 'first-order-transport-fleet']),
    ('first-order', 'navy', 'interdictor-resurgent-group', 'First Order Interdictor Group', 'Support ship', 'Interdictor', 'First Order interdictor groups pulled Resistance ships from hyperspace for destruction by waiting Star Destroyer battle groups. FSIB intelligence fed interdictor positioning data to maximize ambush success. Resistance pilots learned to fear gravity well signatures along smuggler routes.', '#450a0a', ['first-order-security-bureau-infantry', 'resurgent-class-star-destroyer', 'finalizer-battle-group']),
    ('first-order', 'navy', 'kylo-ren-command-group', 'Kylo Ren Command Group', 'Task force', 'Task force', "Kylo Ren's personal command group combined Knights of Ren, Silencer squadrons, and selected Resurgent-class elements for Force-related missions and high-value target hunts. Ren's volatile command style often bypassed General Hux's formal chain of command. The group pursued Rey and surviving Jedi across multiple sectors.", '#7f1d1d', ['knights-of-ren', 'tie-silencer-squadron', 'supremacy-flagship-group']),
    ('resistance', 'army', 'resistance-troopers', 'Resistance Troopers', 'Infantry', None, "Resistance troopers volunteered from worlds the New Republic abandoned, fighting the First Order with outdated gear and absolute conviction from D'Qar to Crait. They carried salvaged blasters, home-made armor patches, and unit insignia honoring fallen comrades. Every trooper knew the galaxy might never learn their names if they failed.", '#f97316', ['resistance-commandos', 'resistance-navy', 'crait-evacuation-force']),
    ('resistance', 'army', 'resistance-commandos', 'Resistance Commandos', 'Special forces', None, 'Resistance commandos conducted raids on First Order convoys, prisoner liberations, and intelligence extractions with tight cell discipline learned from Rebel veterans. Commando teams supported starfighter operations on Crait and protected evacuation corridors under fire. Their training emphasized improvisation over standardized Academy doctrine.', '#fb923c', ['resistance-troopers', 'resistance-pathfinder-team', 'resistance-transport-group']),
    ('resistance', 'army', 'resistance-pathfinder-team', 'Resistance Pathfinder Team', 'Special forces', None, "Pathfinder teams marked landing zones and scouted First Order garrisons ahead of Poe Dameron's strike missions. On Crait they identified salt-plain trenches suitable for laser cannon emplacements against walker advances. Pathfinders often operated alone for weeks behind enemy lines.", '#ea580c', ['resistance-commandos', 'resistance-artillery-crew', 'crait-evacuation-force']),
    ('resistance', 'army', 'resistance-artillery-crew', 'Resistance Artillery Crew', 'Artillery', None, 'Resistance artillery crews operated v-120 and similar emplacements on Crait, scoring hits on First Order AT-M6 walkers before being overrun. Artillery units trained to fire and reposition under orbital bombardment conditions. Their courage bought minutes that saved surviving Resistance leadership.', '#fdba74', ['resistance-pathfinder-team', 'resistance-troopers', 'crait-evacuation-force']),
    ('resistance', 'army', 'resistance-security-detachment', 'Resistance Security Detachment', 'Security', None, "Security detachments guarded General Leia Organa, Resistance bases, and sensitive intelligence archives on D'Qar and mobile command ships. Detachment troopers screened recruits and monitored for First Order infiltrators after Starkiller Base's devastation. Leia's protection was their highest priority mission.", '#f97316', ['resistance-troopers', 'resistance-intelligence-corps', 'raptor-squadron']),
    ('resistance', 'army', 'resistance-intelligence-corps', 'Resistance Intelligence Corps', 'Intelligence', None, "Resistance intelligence corps analyzed First Order fleet movements, decrypted comm traffic, and coordinated with smugglers for supply route security. Intelligence failures after Hosnian Prime's destruction forced the Resistance into desperate hiding. Corps analysts worked alongside Bothan legacy networks and Republic veterans.", '#fb923c', ['resistance-security-detachment', 'resistance-commandos', 'resistance-navy']),
    ('resistance', 'army', 'resistance-medical-corps', 'Resistance Medical Corps', 'Support', None, "Medical corps personnel treated casualties from Starkiller Base's aftermath through Crait's evacuation under impossible supply constraints. Field medics aboard frigates and in trench lines stabilized wounded pilots and troopers for hyperspace transit. Their triage decisions saved leaders who continued the fight after D'Qar's loss.", '#ea580c', ['resistance-troopers', 'resistance-transport-group', 'resistance-navy']),
    ('resistance', 'army', 'resistance-engineer-corps', 'Resistance Engineer Corps', 'Combat engineers', None, "Engineer corps maintained T-70 X-wings, MG-100 bombers, and base shield systems with scavenged parts and Mon Calamari technical manuals. Engineers wired Crait's bunker doors and repaired laser cannons between walker assault waves. Their ingenuity compensated for the Resistance's funding gap versus the First Order.", '#fdba74', ['resistance-artillery-crew', 'resistance-starfighter-corps', 'resistance-navy']),
    ('resistance', 'army', 'resistance-vanguard-infantry', 'Resistance Vanguard Infantry', 'Assault', None, "Vanguard infantry led boarding actions against First Order transports and secured beachheads during Poe Dameron's aggressive strike doctrine. Vanguard units accepted high casualties to disrupt enemy timetables and protect civilian evacuations. Their red armbands marked them as volunteers for the most dangerous assignments.", '#f97316', ['resistance-commandos', 'resistance-troopers', 'resistance-starfighter-corps']),
    ('resistance', 'army', 'resistance-garrison-dqar', "D'Qar Resistance Garrison", 'Garrison', None, "The D'Qar garrison protected the Resistance's primary base until First Order fleet bombardment forced evacuation after Starkiller Base's destruction. Garrison troopers coordinated with starfighter wings and ground artillery during the desperate holding action. D'Qar's loss scattered the Resistance into hunted fugitives.", '#fb923c', ['resistance-troopers', 'resistance-navy', 'resistance-bombers']),
    ('resistance', 'army', 'resistance-crait-garrison', 'Crait Resistance Garrison', 'Garrison', None, "Crait's garrison hid in an abandoned Rebel-era mine until First Order trackers located the redoubt, triggering the salt-plain battle. Troopers fought from trenches alongside v-120 crews and v-4 speeders against AT-M6 mega-walkers. Luke Skywalker's projection allowed the garrison's survivors to escape aboard the Millennium Falcon.", '#ea580c', ['resistance-artillery-crew', 'resistance-pathfinder-team', 'crait-evacuation-force']),
    ('resistance', 'army', 'resistance-pilot-infantry', 'Resistance Pilot Infantry', 'Combined arms', None, "When not flying, Resistance pilots like Poe Dameron and Jess Pava fought as infantry during base defenses and evacuations with sidearms and tactical training. Pilot-infantry doctrine reflected the Resistance's inability to maintain separate ground armies at full strength. Every pilot expected to defend their hangar bay to the last.", '#fdba74', ['resistance-starfighter-corps', 'resistance-troopers', 'raptor-squadron']),
    ('resistance', 'army', 'resistance-droid-infantry-support', 'Resistance Droid Infantry Support', 'Support', None, 'Modified astromechs, protocol droids, and combat droids assisted Resistance ground operations with repair, translation, and occasional direct combat roles. BB-8 and similar units became symbols of Resistance resourcefulness. Droid support freed human soldiers for frontline duty during manpower crises.', '#f97316', ['resistance-engineer-corps', 'resistance-troopers', 'resistance-transport-group']),
    ('resistance', 'army', 'resistance-outer-rim-cell-infantry', 'Outer Rim Resistance Cell Infantry', 'Irregular infantry', None, 'Scattered Outer Rim cells maintained harassing operations against First Order occupation forces when central command could not coordinate fleet support. Cell infantry used local terrain knowledge and guerrilla tactics learned from Rebel Alliance veterans. These units kept hope alive on worlds the New Republic forgot.', '#fb923c', ['resistance-troopers', 'resistance-intelligence-corps', 'resistance-transport-group']),
    ('resistance', 'army', 'resistance-training-battalion', 'Resistance Training Battalion', 'Training command', None, "Training battalions rushed new volunteers through accelerated programs after Hosnian Prime's destruction depleted experienced personnel. Instructors included Clone Wars and Galactic Civil War veterans passing on hard-won lessons. Training quality suffered under time pressure but produced soldiers willing to die for the cause.", '#ea580c', ['resistance-troopers', 'resistance-medical-corps', 'resistance-garrison-dqar']),
    ('resistance', 'army', 'resistance-evacuation-corps', 'Resistance Evacuation Corps', 'Support', None, "Evacuation corps organized civilian and military retreats from D'Qar, Crait, and threatened worlds under First Order bombardment. Corps teams prioritized leaders, children, and critical intelligence archives during timed escape windows. Their work prevented total annihilation of the Resistance movement.", '#fdba74', ['crait-evacuation-force', 'resistance-transport-group', 'resistance-medical-corps']),
    ('resistance', 'navy', 'resistance-navy', 'Resistance Navy', 'Fleet command', 'Task force', "The Resistance Navy under General Leia Organa and Admiral Ackbar's legacy operated a handful of Mon Calamari cruisers, frigates, and corvettes against a vastly superior First Order fleet. Naval doctrine emphasized hit-and-run strikes and evacuation over fleet engagements. Every ship lost was irreplaceable without New Republic support.", '#fb923c', ['resistance-starfighter-corps', 'resistance-bombers', 'raptor-squadron']),
    ('resistance', 'navy', 'resistance-starfighter-corps', 'Resistance Starfighter Corps', 'Starfighter command', 'Starfighter wing', "Resistance Starfighter Corps flew T-70 X-wings, A-wings, and older craft salvaged from New Republic mothballs under Poe Dameron's aggressive leadership. Starfighter corps doctrine favored daring raids over defensive patrols to compensate for numerical inferiority. Pilots like Temmin Wexley and Jess Pava represented a new generation of aces.", '#f97316', ['raptor-squadron', 'black-squadron', 'resistance-navy']),
    ('resistance', 'navy', 'resistance-bombers', 'Resistance Bomber Command', 'Starfighter unit', 'Bomber wing', "Resistance bomber command flew MG-100 StarFortress bombers in tight formation doctrine designed to saturate point defenses—epitomized by Cobalt Hammer at D'Qar's evacuation battle. Bomber crews suffered catastrophic losses but destroyed First Order Dreadnought Fulminatrix in a pyrrhic victory. Paige Tico's sacrifice became Resistance legend.", '#fdba74', ['resistance-navy', 'resistance-starfighter-corps', 'crait-evacuation-force']),
    ('resistance', 'navy', 'raptor-squadron', 'Raptor Squadron', 'Starfighter unit', 'Starfighter wing', "Raptor Squadron flew T-70 X-wings in Poe Dameron's preferred strike package configuration for deep raids into First Order space. The squadron screened bombers and conducted reconnaissance ahead of fleet movements. Raptor pilots trained for the tight comm discipline required in Resistance cell operations.", '#ea580c', ['resistance-starfighter-corps', 'black-squadron', 'resistance-navy']),
    ('resistance', 'navy', 'black-squadron', 'Black Squadron', 'Starfighter unit', 'Starfighter wing', 'Black Squadron conducted intelligence-gathering starfighter missions for Leia Organa before open war reignited, operating from hidden bases and mobile platforms. Poe Dameron led Black Squadron through encounters that mapped First Order fleet buildup. The squadron transitioned into frontline combat roles after Hosnian Prime.', '#fb923c', ['raptor-squadron', 'resistance-intelligence-corps', 'resistance-starfighter-corps']),
    ('resistance', 'navy', 'mc85-star-cruiser-group', 'MC85 Star Cruiser Group', 'Capital ship', 'Cruiser', "MC85 Star Cruisers like the Raddus served as Resistance flagships with experimental deflector shields and heavy starfighter complements. Cruiser groups led evacuations from D'Qar and attempted to protect fleeing transports against Mandator IV siege guns. The Raddus's Holdo maneuver destroyed a pursuing Star Destroyer at catastrophic cost.", '#f97316', ['resistance-navy', 'resistance-bombers', 'resistance-transport-group']),
    ('resistance', 'navy', 'resistance-frigate-escort-group', 'Resistance Frigate Escort Group', 'Escort ship', 'Frigate', "Resistance frigates screened larger cruisers and protected transport convoys during evacuations with limited firepower but skilled crews. Escort groups sacrificed themselves repeatedly to buy time for Leia Organa's command staff to escape. Frigate captains became legends among Resistance recruits.", '#ea580c', ['mc85-star-cruiser-group', 'resistance-transport-group', 'resistance-navy']),
    ('resistance', 'navy', 'resistance-corvette-strike-group', 'Resistance Corvette Strike Group', 'Escort ship', 'Corvette', 'Resistance corvettes conducted hit-and-run strikes against First Order supply lines and rescued stranded cells from Outer Rim worlds. Strike groups relied on speed and surprise rather than sustained combat. Corvette crews often operated with minimal crew and maximum courage.', '#fb923c', ['resistance-outer-rim-cell-infantry', 'resistance-navy', 'resistance-starfighter-corps']),
    ('resistance', 'navy', 'resistance-transport-group', 'Resistance Transport Group', 'Support ship', 'Transport', 'Transport groups moved refugees, troops, and supplies between hidden bases aboard GR-75 and successor hulls under constant First Order pursuit. Transport pilots flew the most thankless and dangerous missions in the Resistance order of battle. Successful transports preserved the movement after every major defeat.', '#fdba74', ['resistance-evacuation-corps', 'resistance-medical-corps', 'resistance-frigate-escort-group']),
    ('resistance', 'navy', 'crait-evacuation-force', 'Crait Evacuation Force', 'Task force', 'Task force', 'The Crait evacuation force combined trench garrison, v-4 speeders, and starfighter cover to extract surviving Resistance leaders through a hidden mountain passage while Luke Skywalker distracted Kylo Ren. Force coordination between ground and naval elements barely succeeded against overwhelming First Order numbers. The evacuation preserved hope for a galactic counteroffensive.', '#f97316', ['resistance-crait-garrison', 'resistance-bombers', 'mc85-star-cruiser-group']),
    ('resistance', 'navy', 'dqar-evacuation-fleet', "D'Qar Evacuation Fleet", 'Task force', 'Task force', "The D'Qar evacuation fleet fought a rear-guard action against First Order dreadnought fire while bombers attempted to destroy the Fulminatrix before it wiped the base. Admiral Holdo's leadership and Paige Tico's bomber run defined the battle's desperate heroism. The fleet's survival allowed regrouping at Crait.", '#ea580c', ['resistance-garrison-dqar', 'resistance-bombers', 'mc85-star-cruiser-group']),
    ('resistance', 'navy', 'resistance-a-wing-interceptor-wing', 'Resistance A-wing Interceptor Wing', 'Starfighter unit', 'Starfighter wing', "Resistance A-wings provided fleet screening and pursued First Order TIE fighters during evacuation battles with the same speed that defined Rebel Alliance interceptor doctrine. A-wing pilots protected transports during D'Qar and Crait retreats. Their green laser fire marked last stands against overwhelming odds.", '#fb923c', ['resistance-starfighter-corps', 'resistance-frigate-escort-group', 'raptor-squadron']),
    ('resistance', 'navy', 'resistance-legacy-cruiser-group', 'Resistance Legacy Cruiser Group', 'Capital ship', 'Cruiser', 'Legacy Mon Calamari cruisers from Galactic Civil War-era conversions supplemented MC85 flagships with battle-tested hulls and veteran crews. Legacy groups carried the institutional memory of Endor and Scarif into fights against Resurgent-class enemies. Each cruiser had a history Resistance propaganda celebrated.', '#f97316', ['mc85-star-cruiser-group', 'resistance-navy', 'resistance-legacy-pilot-veterans']),
    ('resistance', 'navy', 'resistance-legacy-pilot-veterans', 'Resistance Veteran Pilot Wing', 'Starfighter unit', 'Starfighter wing', 'Veteran pilot wings included Galactic Civil War survivors like Nien Nunb and others who flew against Imperial and now First Order enemies across decades. Their experience stabilized green recruits during catastrophic losses. Veteran wings transferred tactical knowledge no simulator could teach.', '#ea580c', ['resistance-starfighter-corps', 'resistance-legacy-cruiser-group', 'black-squadron']),
    ('new-republic', 'army', 'new-republic-soldiers', 'New Republic Soldiers', 'Infantry', None, 'New Republic soldiers served as peacekeepers on member worlds after the Galactic Civil War, transitioning from Rebel guerrillas to garrison troops with mixed success. Demobilization policies left many sectors under-defended when the First Order rose in the Unknown Regions. Soldiers wore standardized gear honoring both Alliance and Imperial-era equipment legacies.', '#ffd166', ['new-republic-defense-fleet', 'senate-guard-battalion', 'rapier-squadron']),
    ('new-republic', 'army', 'new-republic-army-legion', 'New Republic Army Legion', 'Legion', None, "Army legions maintained planetary garrisons and responded to regional crises under Senate authorization after Endor's victory. Legion strength varied by sector funding and political will, creating vulnerabilities First Order planners exploited. Chandrila and Hosnian Prime debates shaped legion deployment priorities.", '#fbbf24', ['new-republic-soldiers', 'new-republic-special-forces', 'hosnian-home-guard']),
    ('new-republic', 'army', 'new-republic-special-forces', 'New Republic Special Forces', 'Special forces', None, 'New Republic special forces hunted Imperial warlords, rescued hostages, and conducted counterterrorism before the First Order threat fully emerged. SF units operated with legal constraints Rebel commandos never faced under wartime emergency powers. Their effectiveness declined as budgets shifted to demilitarization.', '#f59e0b', ['new-republic-soldiers', 'new-republic-intelligence-infantry', 'rapier-squadron']),
    ('new-republic', 'army', 'new-republic-intelligence-infantry', 'New Republic Intelligence Infantry', 'Intelligence', None, "Intelligence infantry supported field operatives with security detachments and tactical teams during sensitive missions against remnant Imperial factions. NRI teams tracked Operation: Cinder survivors and shadow fleet movements. Intelligence failures regarding the First Order's buildup became a historic controversy after Hosnian Prime.", '#eab308', ['new-republic-special-forces', 'senate-guard-battalion', 'new-republic-defense-fleet']),
    ('new-republic', 'army', 'senate-guard-battalion', 'New Republic Senate Guard', 'Elite guard', None, 'Senate Guard battalions protected the Galactic Senate on Hosnian Prime and earlier capitals with ceremonial and combat roles blending Alderaanian and Coruscant traditions. Guards died defending the Senate chamber when Starkiller Base destroyed the Hosnian system. Their crimson and white armor marked democratic authority.', '#ca8a04', ['new-republic-soldiers', 'hosnian-home-guard', 'new-republic-defense-fleet']),
    ('new-republic', 'army', 'hosnian-home-guard', 'Hosnian Home Guard', 'Garrison', None, "Hosnian Home Guard maintained planetary defense forces for the New Republic capital world before its annihilation. Guard units coordinated with orbital fleets and Senate security during peacetime emergencies. Starkiller Base's beam ended the Home Guard's existence in an instant alongside the Senate.", '#fbbf24', ['senate-guard-battalion', 'new-republic-defense-fleet', 'new-republic-army-legion']),
    ('new-republic', 'army', 'chandrila-peacekeeping-corps', 'Chandrila Peacekeeping Corps', 'Peacekeeping', None, "Chandrila peacekeeping corps deployed from Mon Mothma's homeworld to mediate disputes and support reconstruction on war-scarred planets. Peacekeepers carried weapons but prioritized diplomacy and humanitarian aid. Their missions represented the New Republic's idealistic founding vision before realpolitik eroded funding.", '#ffd166', ['new-republic-soldiers', 'new-republic-army-legion', 'new-republic-medical-corps']),
    ('new-republic', 'army', 'new-republic-medical-corps', 'New Republic Medical Corps', 'Support', None, "Medical corps teams treated veterans, refugees, and civilian casualties from Imperial remnant attacks across the post-Endor period. Medical infrastructure became a New Republic pride point and recruitment tool. Corps personnel later joined Resistance medical units after Hosnian Prime's fall.", '#f59e0b', ['chandrila-peacekeeping-corps', 'new-republic-soldiers', 'new-republic-transport-command']),
    ('new-republic', 'army', 'new-republic-engineer-legion', 'New Republic Engineer Legion', 'Combat engineers', None, "Engineer legions rebuilt cities, cleared minefields, and decommissioned Imperial war machines under Senate reconstruction mandates. Engineering projects on Jakku and other battlefields symbolized hope after the Empire's defeat. Demilitarization reduced engineer military training just as new threats emerged.", '#eab308', ['new-republic-army-legion', 'new-republic-transport-command', 'new-republic-defense-fleet']),
    ('new-republic', 'army', 'new-republic-planetary-defense-militia', 'Planetary Defense Militia', 'Militia', None, 'Member world militias supplemented New Republic legions with local troops responsible for immediate planetary defense under Senate treaties. Militia quality varied enormously between wealthy Core worlds and impoverished Outer Rim members. First Order invasion plans counted on militia collapse in many sectors.', '#ca8a04', ['new-republic-soldiers', 'new-republic-army-legion', 'new-republic-corvette-patrol']),
    ('new-republic', 'army', 'new-republic-veterans-corps', 'New Republic Veterans Corps', 'Reserve', None, 'Veterans corps organized former Rebel and Imperial defectors into reserve units for emergencies that Senate politics often failed to activate in time. Veterans mentored new soldiers and preserved tactical doctrine from the Galactic Civil War. Many veterans later formed the Resistance core when the Senate ignored First Order warnings.', '#fbbf24', ['new-republic-special-forces', 'rapier-squadron', 'new-republic-soldiers']),
    ('new-republic', 'army', 'new-republic-riot-response-unit', 'New Republic Riot Response Unit', 'Security', None, 'Riot response units handled civil unrest on member worlds without deploying full army legions, reflecting New Republic discomfort with military internal policing. Units used non-lethal gear and negotiation training. Their limitations became apparent when syndicate and Imperial remnant agitation escalated.', '#ffd166', ['new-republic-soldiers', 'senate-guard-battalion', 'new-republic-intelligence-infantry']),
    ('new-republic', 'army', 'new-republic-training-command', 'New Republic Training Command', 'Training command', None, "Training command standardized academy curricula across member worlds to professionalize the post-Rebellion military while reducing wartime improvisation. Academy graduates filled fleet and army ranks with varying political loyalties to central authority. Training Command's budget cuts preceded Rapier Squadron's transfer disputes.", '#f59e0b', ['new-republic-soldiers', 'new-republic-veterans-corps', 'rapier-squadron']),
    ('new-republic', 'army', 'new-republic-outer-rim-garrison', 'Outer Rim Garrison Command', 'Garrison', None, "Outer Rim garrisons maintained the New Republic's visible presence on frontier worlds where Imperial warlords and later First Order agents recruited disaffected populations. Underfunded garrisons could not prevent the Unknown Regions buildup Leia Organa warned about. Garrison commanders often operated with minimal Senate support.", '#eab308', ['new-republic-army-legion', 'new-republic-planetary-defense-militia', 'outer-rim-patrol-fleet']),
    ('new-republic', 'army', 'new-republic-disarmament-corps', 'New Republic Disarmament Corps', 'Support', None, 'Disarmament corps supervised Imperial weapon decommissioning and treaty compliance inspections mandated by post-Endor accords. Corps teams visited shipyards and bunker complexes to verify dismantling schedules Senate factions debated endlessly. First Order secret rearmament violated treaties disarmament corps were denied resources to enforce.', '#ca8a04', ['new-republic-engineer-legion', 'new-republic-intelligence-infantry', 'new-republic-defense-fleet']),
    ('new-republic', 'army', 'new-republic-joint-task-force', 'New Republic Joint Task Force', 'Combined arms', None, 'Joint task forces paired army legions with fleet elements for major remnant Imperial operations during the decade after Endor. Task force doctrine preserved Rebel Alliance combined arms lessons before fleet-army integration atrophied under peacetime bureaucracy. Joint commands became models Resistance leaders wished the Senate had maintained.', '#fbbf24', ['new-republic-army-legion', 'new-republic-defense-fleet', 'new-republic-special-forces']),
    ('new-republic', 'navy', 'new-republic-defense-fleet', 'New Republic Defense Fleet', 'Fleet command', 'Task force', "The New Republic Defense Fleet succeeded the Rebel Alliance Navy as the galaxy's largest military force before demilitarization shrank its readiness. Defense Fleet squadrons policed trade routes and hunted Imperial holdouts from Jakku through the Outer Rim. Starkiller Base destroyed much of the fleet alongside the Senate in the Hosnian system.", '#ffd166', ['mon-calamari-new-republic-cruiser-group', 'rapier-squadron', 'new-republic-soldiers']),
    ('new-republic', 'navy', 'mon-calamari-new-republic-cruiser-group', 'New Republic Mon Calamari Cruiser Group', 'Capital ship', 'Cruiser', "Mon Calamari cruiser groups remained the New Republic's premier capital ship formations, built in shipyards that had supplied the Rebel Alliance. Cruiser groups patrolled member worlds and participated in remnant Imperial engagements. Many crews later defected to the Resistance when the Senate failed to act against the First Order.", '#fbbf24', ['new-republic-defense-fleet', 'nebulon-k-frigate-group', 'new-republic-starfighter-corps']),
    ('new-republic', 'navy', 'nebulon-k-frigate-group', 'Nebulon-K Frigate Group', 'Escort ship', 'Frigate', 'Nebulon-K and successor frigate classes escorted New Republic convoys and supported cruiser groups in anti-piracy operations. Frigate groups maintained the logistics chain connecting Core member worlds to Outer Rim territories. Underfunded frigate patrols left smuggler routes open for First Order infiltration.', '#f59e0b', ['mon-calamari-new-republic-cruiser-group', 'new-republic-corvette-patrol', 'new-republic-transport-command']),
    ('new-republic', 'navy', 'new-republic-corvette-patrol', 'New Republic Corvette Patrol', 'Escort ship', 'Corvette', "Corvette patrol squadrons operated on frontier sectors where larger warships rarely ventured, inspecting cargo and responding to distress calls. Patrol corvettes were often the only New Republic military presence on disputed worlds. Poe Dameron's early career included corvette patrol assignments before Rapier Squadron.", '#eab308', ['nebulon-k-frigate-group', 'new-republic-planetary-defense-militia', 'outer-rim-patrol-fleet']),
    ('new-republic', 'navy', 'rapier-squadron', 'Rapier Squadron', 'Starfighter unit', 'Starfighter wing', "Rapier Squadron flew T-85 and T-70 X-wings under New Republic authorization before Poe Dameron's transfer disputes and eventual Resistance defection. The squadron hunted remnant Imperial forces and tested New Republic starfighter procurement policies. Rapier pilots represented the best the Defense Fleet produced before demilitarization.", '#ca8a04', ['new-republic-starfighter-corps', 'new-republic-defense-fleet', 'new-republic-veterans-corps']),
    ('new-republic', 'navy', 'new-republic-starfighter-corps', 'New Republic Starfighter Corps', 'Starfighter command', 'Starfighter wing', 'Starfighter corps integrated X-wing, A-wing, and Y-wing units across Defense Fleet carrier groups with standardized training from New Republic academies. Corps doctrine emphasized defensive patrol over offensive deep strikes compared to Rebel Alliance aggression. Many corps pilots joined the Resistance after Hosnian Prime.', '#fbbf24', ['rapier-squadron', 'new-republic-defense-fleet', 'mon-calamari-new-republic-cruiser-group']),
    ('new-republic', 'navy', 'new-republic-bomber-wing', 'New Republic Bomber Wing', 'Starfighter unit', 'Bomber wing', 'Bomber wings provided fleet strike capability against remnant Imperial dreadnoughts and pirate fortress worlds during post-Endor consolidation campaigns. New Republic bomber doctrine favored precision over the mass casualty assaults wartime Rebel units accepted. Bomber wings mothballed as Senate budgets shrank.', '#ffd166', ['new-republic-starfighter-corps', 'new-republic-defense-fleet', 'new-republic-joint-task-force']),
    ('new-republic', 'navy', 'new-republic-transport-command', 'New Republic Transport Command', 'Support ship', 'Transport', 'Transport command moved peacekeepers, humanitarian aid, and reconstruction supplies across member worlds under Senate mandates. Transport fleets supported engineer legions and medical corps deployments. Command vessels later smuggled Resistance supplies when official policy forbade military aid.', '#f59e0b', ['new-republic-medical-corps', 'new-republic-engineer-legion', 'nebulon-k-frigate-group']),
    ('new-republic', 'navy', 'outer-rim-patrol-fleet', 'Outer Rim Patrol Fleet', 'Task force', 'Task force', 'Outer Rim patrol fleets maintained visible New Republic authority on frontier hyperspace routes where Imperial warlords and syndicates competed for influence. Fleet commanders warned Senate committees about Unknown Regions anomalies years before Starkiller Base fired. Underfunding made patrol fleets symbolic rather than deterrent.', '#eab308', ['new-republic-outer-rim-garrison', 'new-republic-corvette-patrol', 'new-republic-defense-fleet']),
    ('new-republic', 'navy', 'hosnian-defense-squadron', 'Hosnian System Defense Squadron', 'Task force', 'Defense fleet', "Hosnian system defense squadrons protected the Senate capital with cruiser groups and starfighter wings that proved utterly inadequate against Starkiller Base's superweapon beam. Defense planners assumed threats would come from conventional fleets rather than planet-killing weapons. The squadron's destruction ended the New Republic as a governing force.", '#ca8a04', ['hosnian-home-guard', 'senate-guard-battalion', 'mon-calamari-new-republic-cruiser-group']),
    ('new-republic', 'navy', 'jakkuvian-remnant-hunt-group', 'Jakku Remnant Hunt Group', 'Task force', 'Task force', "Jakku remnant hunt groups pursued Imperial holdouts after the Battle of Jakku—the Galactic Civil War's last major fleet action— enforcing the Galactic Concordance. Hunt groups destroyed or captured Imperial vessels refusing surrender terms. Their success created false confidence that the Empire was truly finished.", '#fbbf24', ['new-republic-defense-fleet', 'new-republic-joint-task-force', 'new-republic-veterans-corps']),
    ('new-republic', 'navy', 'new-republic-scout-frigate-squadron', 'New Republic Scout Frigate Squadron', 'Escort ship', 'Frigate', 'Scout frigate squadrons mapped Unknown Regions boundaries and monitored Imperial remnant movements with long-range sensors and minimal armament. Scout data Leia Organa cited was often dismissed by Senate factions prioritizing trade over defense. Scout squadrons were among the first units the First Order targeted covertly.', '#ffd166', ['outer-rim-patrol-fleet', 'new-republic-intelligence-infantry', 'new-republic-corvette-patrol']),
    ('new-republic', 'navy', 'new-republic-carrier-battle-group', 'New Republic Carrier Battle Group', 'Capital ship', 'Carrier', 'Carrier battle groups centered on Mon Calamari cruisers with expanded hangar capacity for starfighter corps deployment across multiple sectors simultaneously. Battle groups represented peak New Republic power projection before fleet decommissioning programs. Resistance leaders wished at least one battle group had survived Hosnian Prime intact.', '#f59e0b', ['mon-calamari-new-republic-cruiser-group', 'new-republic-starfighter-corps', 'new-republic-defense-fleet']),
    ('mandalorian', 'army', 'death-watch', 'Death Watch', 'Mandalorian clan', None, "Death Watch revived Mandalorian warrior traditions in opposition to Duchess Satine Kryze's pacifist New Mandalorian government on Mandalore. Led by Pre Vizsla and later allied with Darth Maul, Death Watch warriors wore distinctive blue and grey armor with jetpacks and WESTAR blasters. Their coup attempts reshaped Mandalore's politics for decades.", '#64748b', ['nite-owls', 'mandalorian-super-commandos', 'komrk-class-assault-wing']),
    ('mandalorian', 'army', 'nite-owls', 'Nite Owls', 'Mandalorian clan', None, "Bo-Katan Kryze's Nite Owls broke from Death Watch after Maul's takeover, fighting to restore Mandalore with owl-marked armor and coordinated jetpack assaults. Nite Owls allied with Republic and later Rebel forces against Imperial occupation. Their legacy continued through Bo-Katan's claim to the Darksaber and Mandalorian throne.", '#475569', ['death-watch', 'mandalorian-resistance', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-super-commandos', 'Mandalorian Super Commandos', 'Special forces', None, "Gar Saxon's Imperial-aligned super commandos enforced Moff Gideon and Imperial authority on Mandalore with red and black armor variants. Super commandos hunted Jedi survivors and suppressed Mandalorian culture during the Great Purge. Their betrayal of Mandalorian honor made them enemies of Bo-Katan's resistance.", '#334155', ['death-watch', 'imperial-occupation-garrison', 'komrk-class-assault-wing']),
    ('mandalorian', 'army', 'mandalorian-resistance', 'Mandalorian Resistance', 'Resistance movement', None, "Mandalorian resistance cells fought Imperial occupation after the Night of a Thousand Tears and the Great Purge scattered survivors across the galaxy. Resistance fighters preserved beskar forging traditions and clan identities in hiding. Din Djarin and Bo-Katan's generation inherited their war against Imperial and remnant forces.", '#64748b', ['nite-owls', 'mandalorian-covert-warriors', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-covert-warriors', 'Mandalorian Covert Warriors', 'Covert clan', None, "Hidden Mandalorian covert cells like Din Djarin's Tribe of two maintained the Way—never removing helmets among outsiders—while conducting bounty hunting and resistance operations. Covert warriors followed ancient religious codes that clashed with Bo-Katan's more pragmatic leadership. Their secrecy preserved culture the Empire tried to erase.", '#475569', ['mandalorian-resistance', 'death-watch', 'komrk-class-assault-wing']),
    ('mandalorian', 'army', 'children-of-the-watch', 'Children of the Watch', 'Religious order', None, "Children of the Watch preserved Mandalorian faith and helmet traditions in secret enclaves after the Great Purge scattered mainstream clans. Their orthodox interpretation of the Way created tension with Bo-Katan's Nite Owls and other helmet-optional Mandalorians. Din Djarin's tribe belonged to this hidden religious movement.", '#334155', ['mandalorian-covert-warriors', 'mandalorian-resistance', 'mandalorian-training-cadre']),
    ('mandalorian', 'army', 'mandalorian-training-cadre', 'Mandalorian Training Cadre', 'Training command', None, 'Training cadres on Mandalore and hidden worlds taught jetpack combat, blaster marksmanship, and beskar smithing to new generations before Imperial purges decimated instructors. Cadre veterans became bounty hunters and mercenaries across the Outer Rim. Their teachings preserved Mandalorian martial culture in exile.', '#64748b', ['death-watch', 'children-of-the-watch', 'mandalorian-mercenary-company']),
    ('mandalorian', 'army', 'mandalorian-mercenary-company', 'Mandalorian Mercenary Company', 'Mercenary force', None, "Mandalorian mercenary companies sold elite infantry to governments, syndicates, and private clients when clan politics or economic necessity demanded contracts outside traditional honor codes. Companies maintained internal honor rules distinct from Mandalorian government service. Jango Fett's legacy influenced how galactic clients valued Mandalorian soldiers.", '#475569', ['mandalorian-training-cadre', 'mandalorian-super-commandos', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-jetpack-assault-battalion', 'Mandalorian Jetpack Assault Battalion', 'Airborne', None, 'Jetpack assault battalions combined vertical envelopment with blaster carbine strikes—a signature Mandalorian tactic from the Mandalorian Wars through Clone Wars sieges. Battalions breached fortress walls and boarded vessels with coordinated jetpack waves. Their tactics influenced clone commando training on Kamino.', '#334155', ['death-watch', 'nite-owls', 'komrk-class-assault-wing']),
    ('mandalorian', 'army', 'mandalorian-beskar-vanguard', 'Mandalorian Beskar Vanguard', 'Heavy infantry', None, 'Beskar vanguard units wore full beskar armor capable of deflecting blaster bolts and even glancing lightsaber strikes in close combat. Vanguard soldiers led assaults against droid armies and Imperial garrisons where lighter troops would falter. Beskar scarcity after the Purge made vanguard units increasingly rare and precious.', '#64748b', ['mandalorian-jetpack-assault-battalion', 'mandalorian-resistance', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-saboteur-cells', 'Mandalorian Saboteur Cells', 'Special forces', None, 'Saboteur cells infiltrated Imperial factories, shipyards, and governance centers to destroy beskar confiscation programs and assassinate collaborators like Gar Saxon. Cells operated in pairs or squads with minimal support for months-long missions. Saboteur successes slowed but could not stop the Great Purge.', '#475569', ['mandalorian-resistance', 'nite-owls', 'mandalorian-super-commandos']),
    ('mandalorian', 'army', 'mandalorian-clan-kestis-allied-warband', 'Clan Allied Warband', 'Clan militia', None, "Allied warbands united multiple Mandalorian clans under temporary leadership for specific campaigns against Maul's Shadow Collective or Imperial occupation forces. Warbands pooled jetpack infantry, speeder pilots, and artillery for coordinated planetary operations. Clan politics often dissolved warbands after immediate threats passed.", '#334155', ['death-watch', 'nite-owls', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-artillery-line', 'Mandalorian Artillery Line', 'Artillery', None, "Mandalorian artillery lines deployed mass-driver weapons and missile platforms adapted from starship components for siege warfare against fortified cities and Separatist droid foundries. Artillery crews wore lighter armor than vanguard infantry but maintained Mandalorian marksmanship standards. Siege lines featured prominently in Mandalore's internal civil wars.", '#64748b', ['mandalorian-jetpack-assault-battalion', 'mandalorian-clan-kestis-allied-warband', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-speeder-patrol', 'Mandalorian Speeder Patrol', 'Reconnaissance', None, "Speeder patrol units on Mandalore's surface and colony worlds conducted reconnaissance with customized repulsor bikes and sniper rifles before main assault waves committed. Patrol scouts mapped Imperial garrison rotations during resistance campaigns. Speeder units complemented jetpack assault for varied terrain.", '#475569', ['mandalorian-saboteur-cells', 'mandalorian-mercenary-company', 'komrk-class-assault-wing']),
    ('mandalorian', 'army', 'imperial-occupation-garrison', 'Imperial Occupation Garrison on Mandalore', 'Occupation force', None, "Imperial garrisons on Mandalore after the Great Purge hunted surviving Mandalorians and suppressed cultural practices with super commando collaborators and standard stormtrooper battalions. Occupation forces destroyed the Mines of Mandalore and scattered beskar caches. Moff Gideon's rule epitomized Imperial cruelty on the homeworld.", '#334155', ['mandalorian-super-commandos', 'mandalorian-resistance', 'imperial-light-cruiser-patrol']),
    ('mandalorian', 'army', 'mandalorian-bounty-hunter-corps', 'Mandalorian Bounty Hunter Corps', 'Bounty hunters', None, "Mandalorian bounty hunters including Din Djarin, Boba Fett's lineage, and countless clan exiles operated as elite independent contractors across the galaxy. Hunter corps training emphasized tracking, capture, and survival skills applicable to military operations. The Bounty Hunter Guild relied heavily on Mandalorian reputation for lethal efficiency.", '#64748b', ['mandalorian-mercenary-company', 'mandalorian-covert-warriors', 'mandalorian-fleet']),
    ('mandalorian', 'army', 'mandalorian-liberation-assault-force', 'Mandalorian Liberation Assault Force', 'Combined arms', None, "Liberation assault forces combined Nite Owls, resistance cells, and allied clan warbands for coordinated attempts to retake Mandalore from Imperial and Imperial-remnant control. Assault forces used every available asset—jetpacks, Kom'rk fighters, and sabotage—to breach domed cities. Bo-Katan's campaigns depended on these temporary combined formations.", '#475569', ['nite-owls', 'mandalorian-resistance', 'mandalorian-fleet']),
    ('mandalorian', 'navy', 'mandalorian-fleet', 'Mandalorian Fleet Command', 'Fleet command', 'Task force', "Mandalorian fleet command coordinated Kom'rk-class assault fighters, Fang-class escorts, and captured vessels during clan wars and resistance against Maul and the Empire. Fleet doctrine emphasized fast insertion of jetpack infantry over sustained capital ship duels. Mandalorian naval power peaked during Death Watch's alliance era before Imperial purges.", '#94a3b8', ['komrk-class-assault-wing', 'fang-class-escort-squadron', 'mandalorian-liberation-assault-force']),
    ('mandalorian', 'navy', 'komrk-class-assault-wing', "Kom'rk-class Assault Fighter Wing", 'Starfighter unit', 'Starfighter wing', "Kom'rk-class assault fighters doubled as troop transports, dropping Mandalorian infantry from rotating wings in vertical assault patterns unique to Mandalorian doctrine. Assault wings supported Death Watch coups and Bo-Katan's resistance operations. Their rotating wing design became iconic in Mandalorian military art.", '#64748b', ['mandalorian-fleet', 'mandalorian-jetpack-assault-battalion', 'death-watch']),
    ('mandalorian', 'navy', 'fang-class-escort-squadron', 'Fang-class Escort Squadron', 'Escort ship', 'Corvette', 'Fang-class escort craft protected Mandalorian convoys carrying beskar, refugees, and clan warriors between hidden bases. Escort squadrons fought Imperial interdictors and pirate raiders along smuggler routes. Their compact profiles suited Mandalorian preference for mobile rather than static defense.', '#475569', ['mandalorian-fleet', 'komrk-class-assault-wing', 'mandalorian-resistance']),
    ('mandalorian', 'navy', 'mandalorian-gauntlet-fighter-wing', 'Gauntlet Fighter Wing', 'Starfighter unit', 'Starfighter wing', "Gauntlet fighters served Mandalorian pilots in clan conflicts and mercenary contracts with heavy weapons and rugged construction suited to harsh environments. Fighter wings operated independently of larger fleet command when clans feuded. Gauntlet designs influenced later Kom'rk development.", '#334155', ['komrk-class-assault-wing', 'mandalorian-mercenary-company', 'mandalorian-fleet']),
    ('mandalorian', 'navy', 'mandalorian-boarding-corps', 'Mandalorian Boarding Corps', 'Marines', 'Boarding wing', 'Boarding corps specialized in seizing enemy vessels with jetpack insertion through hangar bays and breaching charges—a tactic Mandalorians perfected against Separatist dreadnoughts and Imperial patrol craft. Boarding teams captured ships for clan fleets short on capital construction capacity. Boarding corps training merged navy and army disciplines.', '#64748b', ['mandalorian-fleet', 'mandalorian-beskar-vanguard', 'fang-class-escort-squadron']),
    ('mandalorian', 'navy', 'shadow-collective-mandalorian-wing', 'Shadow Collective Mandalorian Wing', 'Task force', 'Task force', "During Darth Maul's Shadow Collective period, Mandalorian fighter wings merged with Pyke and Black Sun assets for coordinated underworld warfare against Republic and rival syndicates. Maul's brief rule of Mandalore united Death Watch naval elements under a dark side agenda. The wing dissolved after Maul's defeat and Mandalorian civil war reignited.", '#475569', ['death-watch', 'mandalorian-fleet', 'komrk-class-assault-wing']),
    ('mandalorian', 'navy', 'mandalorian-resistance-strike-flotilla', 'Mandalorian Resistance Strike Flotilla', 'Task force', 'Task force', 'Resistance strike flotillas hit Imperial convoys stealing beskar and transporting super commando reinforcements to Mandalore. Flotillas operated from asteroid bases and mobile repair ships with minimal logistics support. Successful strikes kept Imperial occupation forces isolated and undersupplied.', '#334155', ['mandalorian-resistance', 'fang-class-escort-squadron', 'mandalorian-saboteur-cells']),
    ('mandalorian', 'navy', 'mandalorian-orbital-defense-wing', 'Mandalorian Orbital Defense Wing', 'Task force', 'Defense fleet', 'Orbital defense wings protected Sundari and other Mandalorian dome cities during internal wars and Separatist invasions before Imperial occupation destroyed centralized defense. Defense wings integrated ground-based ion cannons with fighter patrols. Their failure against Imperial orbital bombardment traumatized Mandalorian strategic thinking.', '#64748b', ['mandalorian-fleet', 'mandalorian-artillery-line', 'mandalorian-orbital-salvage-group']),
    ('mandalorian', 'navy', 'mandalorian-orbital-salvage-group', 'Mandalorian Orbital Salvage Group', 'Support ship', 'Transport', 'Salvage groups recovered wreckage from space battles to refit clan fleets and smelt beskar from destroyed armor—a practical necessity for resource-limited Mandalorian warfare. Salvage crews doubled as engineers and fought as marines when intercepted. Their work kept resistance fleets operational despite Imperial industrial superiority.', '#475569', ['mandalorian-fleet', 'mandalorian-resistance-strike-flotilla', 'fang-class-escort-squadron']),
    ('mandalorian', 'navy', 'mandalorian-clan-carrier-group', 'Mandalorian Clan Carrier Group', 'Capital ship', 'Carrier', "Clan carrier groups converted bulk cruisers and captured Separatist vessels into mobile bases for Kom'rk wings and jetpack battalions during multi-clan campaigns. Carrier groups rarely matched Imperial Star Destroyer firepower but excelled at rapid deployment across Mandalore sector worlds. Clan rivalries sometimes prevented unified carrier command.", '#334155', ['mandalorian-fleet', 'komrk-class-assault-wing', 'mandalorian-clan-kestis-allied-warband']),
    ('mandalorian', 'navy', 'imperial-light-cruiser-patrol', 'Imperial Mandalore Sector Patrol', 'Escort ship', 'Cruiser', "Imperial light cruisers patrolled Mandalore sector space hunting resistance flotillas and blockading beskar exports after the Great Purge. Patrol groups coordinated with super commando ground units and Moff Gideon's command structure. Resistance strike flotillas prioritized destroying these patrols to reopen supply lines.", '#64748b', ['imperial-occupation-garrison', 'mandalorian-super-commandos', 'mandalorian-resistance-strike-flotilla']),
    ('mandalorian', 'navy', 'mandalorian-mercenary-fleet-detachment', 'Mandalorian Mercenary Fleet Detachment', 'Task force', 'Task force', 'Mercenary fleet detachments hired Mandalorian fighter wings and escort squadrons to clients including the Confederacy, Hutts, and corporate interests during the Clone Wars and Imperial Era. Detachments maintained clan honor codes even in paid service. Their contracts spread Mandalorian tactical influence across galactic battlefields.', '#475569', ['mandalorian-mercenary-company', 'mandalorian-gauntlet-fighter-wing', 'mandalorian-fleet']),
    ('mandalorian', 'navy', 'mandalorian-hyperspace-raider-squadron', 'Mandalorian Hyperspace Raider Squadron', 'Escort ship', 'Corvette', 'Hyperspace raider squadrons used fast corvettes to intercept convoys in transit, board high-value targets, and vanish before reinforcements arrived—a piracy-adjacent tactic Mandalorian clans used against Imperial supply chains. Raider squadrons required elite pilots and navigators with local route knowledge. Their operations funded resistance cells when beskar alone could not.', '#334155', ['fang-class-escort-squadron', 'mandalorian-saboteur-cells', 'mandalorian-resistance-strike-flotilla']),
    ('other', 'army', 'nightsister-warriors', 'Nightsister Warriors', 'Force cult army', None, "Nightsister warriors of Dathomir wielded Force magick, energy bows, and enchanted staffs in defense of their villages against Separatist invasions and Imperial massacres. Mother Talzin's clan trained assassins and berserkers whose powers differed from Jedi and Sith traditions. The Battle of Dathomir and Imperial orbital bombardment nearly exterminated their order.", '#84cc16', ['nightbrother-warriors', 'dathomir-clan-guard', 'nightsister-swarm-squadron']),
    ('other', 'army', 'nightbrother-warriors', 'Nightbrother Warriors', 'Allied infantry', None, "Nightbrother warriors from Dathomir's male clan served as enforcers, mounts handlers, and melee specialists allied with or subordinate to Nightsister matriarchs. Maul and Savage Opress emerged from Nightbrother trials that pushed candidates to lethal extremes. Nightbrothers fought with gaderffii sticks and brutal close-combat ferocity.", '#65a30d', ['nightsister-warriors', 'dathomir-clan-guard', 'dathomirian-orbital-shaman-guard']),
    ('other', 'army', 'gungan-grand-army', 'Gungan Grand Army', 'Amphibious army', None, "The Gungan Grand Army defended Naboo's oceans and swamps with booma catapults, kaadu cavalry, and shielded infantry at the Battle of the Great Grass Plains. Boss Nass united Bongo submarine forces with land armies to defeat Trade Federation battle droids alongside Queen Amidala. Gungan warriors proved essential to Naboo's liberation.", '#4d7c0f', ['gungan-militiagung', 'naboo-royal-security-forces', 'gungan-submarine-flotilla']),
    ('other', 'army', 'gungan-militiagung', 'Gungan Militiagung', 'Militia', None, 'Militiagung formed the rank-and-file of Gungan military formations with atlatls, spears, and personal energy shields adapted to swamp warfare. Militiagung training emphasized ambush tactics and aquatic mobility foreign to droid armies. Their courage at Grassy Plains redeemed Gungan-Republic relations after initial diplomatic friction.', '#65a30d', ['gungan-grand-army', 'naboo-royal-security-forces', 'gungan-submarine-flotilla']),
    ('other', 'army', 'naboo-royal-security-forces', 'Naboo Royal Security Forces', 'Planetary defense', None, "Naboo Royal Security Forces protected Theed Palace, civilian populations, and planetary sovereignty with security troopers, pilots, and naval elements under the monarchy's command. Captain Panaka and successor leaders coordinated with Gungans during the Trade Federation invasion. Royal Security blended ceremonial guard duties with genuine combat readiness.", '#4d7c0f', ['naboo-royal-handmaidens-detachment', 'gungan-grand-army', 'naboo-n-1-patrol-wing']),
    ('other', 'army', 'naboo-royal-handmaidens-detachment', 'Naboo Royal Handmaidens Detachment', 'Security', None, "Handmaiden detachments served Queen Amidala with concealed weapons, tactical training, and body-double protocols that fooled Trade Federation occupation forces. Handmaidens fought alongside security forces during Theed's liberation with professionalism exceeding typical court attendants. Their service demonstrated Naboo's tradition of hidden strength.", '#84cc16', ['naboo-royal-security-forces', 'naboo-royal-security-forces', 'trade-federation-army']),
    ('other', 'army', 'trade-federation-army', 'Trade Federation Army', 'Corporate army', None, "Trade Federation armies deployed B1 battle droids, AAT tanks, and MTT transports during the Naboo blockade and later Separatist integration under Nute Gunray's authority. Corporate army doctrine prioritized profit preservation and droid expendability over soldier welfare. Federation armies opened the Clone Wars era through Geonosis alliances.", '#a3e635', ['b1-trade-federation-droids', 'corporate-battle-droid-legion', 'lucrehulk-blockade-group']),
    ('other', 'army', 'b1-trade-federation-droids', 'Trade Federation B1 Droid Legion', 'Infantry', None, "Trade Federation B1 droid legions formed the bulk of corporate invasion forces during Naboo's occupation with rigid programming and overwhelming numbers. Droid legions marched through Theed's streets until sabotaged by Anakin Skywalker and coordinated Gungan-Republic counterattacks. Their failure on Naboo foreshadowed broader Separatist droid limitations.", '#84cc16', ['trade-federation-army', 'aat-trade-federation-battalion', 'lucrehulk-blockade-group']),
    ('other', 'army', 'aat-trade-federation-battalion', 'Trade Federation AAT Battalion', 'Armor', None, "Trade Federation AAT battalions supported droid infantry during planetary invasions with heavy laser cannons and troop compartments for battle droids. AATs rolled across Naboo's plains and later Separatist battlefields under corporate and Confederate livery. Their design became standard Separatist armor support.", '#65a30d', ['b1-trade-federation-droids', 'trade-federation-army', 'corporate-battle-droid-legion']),
    ('other', 'army', 'corporate-battle-droid-legion', 'Corporate Sector Battle Droid Legion', 'Corporate army', None, 'Corporate sector legions combined Trade Federation, Commerce Guild, and Techno Union droid assets under Separatist charter during the Clone Wars. Corporate armies fought for profit as much as politics, preserving holdings while Republic forces besieged them. Corporate battle droid legions filled Separatist ranks alongside pure Separatist units.', '#4d7c0f', ['trade-federation-army', 'techno-union-contract-brigade', 'corporate-patrol-frigate-group']),
    ('other', 'army', 'hutt-cartel-enforcers', 'Hutt Cartel Enforcers', 'Criminal army', None, "Hutt Cartel enforcers included Gamorrean guards, Weequay skiff pilots, Nikto soldiers, and hired bounty hunters protecting kajidic palaces and spice routes from Nar Shaddaa to Tatooine. Enforcer armies prioritized intimidation and brutal example over conventional military discipline. Jabba's court exemplified Hutt military excess on a personal scale.", '#bef264', ['hutt-skiff-patrol', 'hutt-palace-guard', 'hutt-yacht-escort-squadron']),
    ('other', 'army', 'hutt-palace-guard', 'Hutt Palace Guard', 'Bodyguard', None, "Palace guards protected Hutt crime lords with layered security—Gamorrean vanguard, hidden snipers, and rancor pits for disposing of failures. Jabba's palace on Tatooine maintained guard rotations that deterred most assassination attempts until Luke Skywalker's rescue mission. Palace guards doubled as executioners and tournament fighters.", '#84cc16', ['hutt-cartel-enforcers', 'hutt-skiff-patrol', 'hutt-yacht-escort-squadron']),
    ('other', 'army', 'crimson-dawn-soldiers', 'Crimson Dawn Soldiers', 'Criminal syndicate', None, "Crimson Dawn soldiers served Maul's shadow syndicate with red-and-black armor, martial discipline exceeding typical criminal thugs, and terror tactics across the underworld. Dawn enforcers seized spice mines, assassinated rivals, and occupied worlds during the Clone Wars power vacuum. Their visibility challenged both Republic law and rival cartels.", '#dc2626', ['crimson-dawn-elite-enforcers', 'black-sun-enforcers', 'crimson-dawn-strike-flotilla']),
    ('other', 'army', 'crimson-dawn-elite-enforcers', 'Crimson Dawn Elite Enforcers', 'Special forces', None, "Elite enforcers conducted Crimson Dawn's most sensitive operations—hostage extraction, Jedi artifact recovery, and coordinated strikes against Black Sun and Pyke holdings. Maul personally trained selected enforcers in Sith-inspired combat forms without granting full dark side initiation. Elite units wore distinctive crimson armor variants.", '#b91c1c', ['crimson-dawn-soldiers', 'nightbrother-warriors', 'crimson-dawn-strike-flotilla']),
    ('other', 'army', 'pyke-syndicate-forces', 'Pyke Syndicate Forces', 'Criminal army', None, "Pyke Syndicate forces guarded spice convoys from Oba Diah with masked infantry, repulsor sled escorts, and brutal enforcement of production quotas on Kessel and affiliated mines. Pyke soldiers served Darth Maul's Shadow Collective before returning to syndicate autonomy. Their distinctive silhouettes marked spice route security.", '#16a34a', ['pyke-spice-guard', 'black-sun-enforcers', 'pyke-spice-hauler-convoy']),
    ('other', 'army', 'pyke-spice-guard', 'Pyke Spice Guard', 'Security', None, "Spice guard units protected refinery complexes and slave labor camps on Kessel with electrostaffs, blasters, and atmospheric conditioning suits for harsh environments. Guard brutality kept production flowing for syndicate profits that funded Shadow Collective operations. Han Solo's Kessel Run escape humiliated a spice guard detachment.", '#15803d', ['pyke-syndicate-forces', 'hutt-cartel-enforcers', 'pyke-spice-hauler-convoy']),
    ('other', 'army', 'black-sun-enforcers', 'Black Sun Enforcers', 'Criminal syndicate', None, "Black Sun enforcers operated as the galaxy's most feared criminal soldiers under Vigo councils from Mustafar to Coruscant's underlevels. Assassin training, cybernetic enhancements, and zero-negotiation doctrine made Black Sun the syndicate others paid tribute to avoid. Maul's Shadow Collective temporarily subordinated Black Sun before internal coups restored independence.", '#14532d', ['black-sun-vigo-guard', 'crimson-dawn-soldiers', 'black-sun-frigate-patrol']),
    ('other', 'army', 'black-sun-vigo-guard', 'Black Sun Vigo Guard', 'Bodyguard', None, 'Vigo guards protected Black Sun leadership with elite marksmanship and loyalty enforced through fear and profit sharing. Guards accompanied Vigos to Shadow Collective meetings and syndicate wars that shaped underworld politics during the Clone Wars. Their black armor and red visor glow became underworld iconography.', '#166534', ['black-sun-enforcers', 'crimson-dawn-elite-enforcers', 'black-sun-frigate-patrol']),
    ('other', 'army', 'techno-union-contract-brigade', 'Techno Union Contract Brigade', 'Corporate army', None, 'Techno Union contract brigades leased droid and organic hybrid forces to Separatist battle groups while preserving corporate ownership of production facilities on Skako Minor and Foerost. Contract terms let Wat Tambor withdraw support when profits turned—creating strategic uncertainty for Confederate command. Brigades fielded experimental droid variants unavailable to standard Separatist armies.', '#84cc16', ['corporate-battle-droid-legion', 'trade-federation-army', 'techno-union-support-fleet']),
    ('other', 'army', 'dathomir-clan-guard', 'Dathomir Clan Guard', 'Planetary defense', None, "Dathomir clan guards protected Nightsister villages with perimeter wards, scout patrols, and magick-infused traps against offworld invaders. Guard traditions blended warrior training with shamanic rituals unique to Dathomir's Force vergence. Imperial massacres targeted clan guards first to break Nightsister defenses.", '#65a30d', ['nightsister-warriors', 'nightbrother-warriors', 'dathomirian-orbital-shaman-guard']),
    ('other', 'navy', 'gungan-submarine-flotilla', 'Gungan Bongo Submarine Flotilla', 'Naval unit', 'Submarine wing', "Gungan Bongo submarines navigated Naboo's ocean depths to transport Grand Army formations and conduct underwater ambushes against Trade Federation MTT convoys. Flotilla pilots used organic propulsion and familiar reef routes invisible to droid sensors. Bongo coordination with surface armies won the Battle of Naboo.", '#4d7c0f', ['gungan-grand-army', 'gungan-militiagung', 'naboo-n-1-patrol-wing']),
    ('other', 'navy', 'naboo-n-1-patrol-wing', 'Naboo N-1 Starfighter Patrol Wing', 'Starfighter unit', 'Starfighter wing', "Naboo N-1 starfighters defended Naboo space with elegant yellow profiles and skilled Royal Security pilots including Anakin Skywalker's historic Boonta Eve victory. Patrol wings destroyed Trade Federation droid control ships and maintained planetary sovereignty in subsequent crises. N-1 designs symbolized Naboo's aesthetic martial pride.", '#84cc16', ['naboo-royal-security-forces', 'gungan-submarine-flotilla', 'lucrehulk-blockade-group']),
    ('other', 'navy', 'lucrehulk-blockade-group', 'Trade Federation Lucrehulk Blockade Group', 'Capital ship', 'Carrier', "Trade Federation Lucrehulk blockade groups encircled Naboo and other target worlds with droid starfighter swarms and landing craft for corporate invasions. Blockade groups represented the Trade Federation's primary naval power before full Separatist integration. Anakin Skywalker destroyed the Naboo blockade control ship from an N-1 fighter.", '#a3e635', ['trade-federation-army', 'b1-trade-federation-droids', 'naboo-n-1-patrol-wing']),
    ('other', 'navy', 'corporate-patrol-frigate-group', 'Corporate Sector Patrol Frigate Group', 'Escort ship', 'Frigate', 'Corporate patrol frigates guarded Commerce Guild and Trade Federation shipping lanes with moderate firepower and heavy legal jurisdiction claims over contested space. Patrol groups harassed Republic inspections and escorted battle droid shipments to Separatist staging areas. Corporate navies blurred lines between security and invasion force.', '#65a30d', ['corporate-battle-droid-legion', 'trade-federation-army', 'techno-union-support-fleet']),
    ('other', 'navy', 'hutt-skiff-patrol', 'Hutt Skiff Patrol Wing', 'Naval unit', 'Patrol wing', "Hutt skiff patrols escorted spice barges through Tatooine's Dune Sea and Nar Shaddaa orbital lanes with repulsorcraft-mounted blaster cannons. Skiff patrols responded faster than capital ships to smuggler raids and rival cartel ambushes. Jabba deployed skiff patrols during Luke Skywalker's Sarlacc execution attempt.", '#bef264', ['hutt-cartel-enforcers', 'hutt-palace-guard', 'hutt-yacht-escort-squadron']),
    ('other', 'navy', 'hutt-yacht-escort-squadron', 'Hutt Yacht Escort Squadron', 'Escort ship', 'Corvette', "Hutt yacht escort squadrons protected crime lord personal vessels with customized fighters and mercenary pilots loyal to kajidic payrolls. Escorts accompanied Jabba's sail barge and orbital pleasure craft through dangerous territories. Squadron quality varied with Hutt wealth and paranoia levels.", '#84cc16', ['hutt-cartel-enforcers', 'hutt-skiff-patrol', 'black-sun-frigate-patrol']),
    ('other', 'navy', 'crimson-dawn-strike-flotilla', 'Crimson Dawn Strike Flotilla', 'Task force', 'Task force', "Crimson Dawn strike flotillas combined fast corvettes and stolen military craft for raids against Black Sun convoys and Republic patrols during Maul's syndicate war. Flotillas operated from hidden bases including Dathomir-adjacent staging points. Maul's personal command prioritized terror over territorial holding.", '#dc2626', ['crimson-dawn-soldiers', 'crimson-dawn-elite-enforcers', 'black-sun-frigate-patrol']),
    ('other', 'navy', 'pyke-spice-hauler-convoy', 'Pyke Spice Hauler Convoy', 'Support ship', 'Transport', 'Pyke spice hauler convoys moved refined spice from Kessel through guarded hyperspace routes with syndicate frigate escorts and armed hauler crews. Convoy losses to smugglers and rival cartels triggered brutal reprisals against nearby populations. Convoy security employed Pyke guard infantry and hired pilots.', '#16a34a', ['pyke-syndicate-forces', 'pyke-spice-guard', 'corporate-patrol-frigate-group']),
    ('other', 'navy', 'black-sun-frigate-patrol', 'Black Sun Frigate Patrol', 'Escort ship', 'Frigate', 'Black Sun frigate patrols enforced syndicate tolls on smuggler routes and protected Vigo convoys through contested sectors from Mustafar to the Outer Rim. Patrol captains held authority to destroy vessels refusing Black Sun tribute. Frigate patrols clashed with Crimson Dawn and Pyke forces during syndicate wars.', '#14532d', ['black-sun-enforcers', 'black-sun-vigo-guard', 'crimson-dawn-strike-flotilla']),
    ('other', 'navy', 'techno-union-support-fleet', 'Techno Union Support Fleet', 'Support ship', 'Transport', "Techno Union support fleets moved droid components, experimental prototypes, and contract brigades between Skako Minor foundries and Separatist battlefronts. Support fleets relied on Corporate Alliance escorts through contested lanes. Wat Tambor's logistical mastery kept Separatist armies supplied longer than Republic strategists expected.", '#84cc16', ['techno-union-contract-brigade', 'corporate-patrol-frigate-group', 'corporate-battle-droid-legion']),
    ('other', 'navy', 'nightsister-swarm-squadron', 'Nightsister Anchorhead Swarm Squadron', 'Starfighter unit', 'Starfighter wing', "Nightsister swarm squadrons piloted unconventional craft and magick-enhanced fighters during defense of Dathomir against Separatist invasions led by General Grievous. Swarm tactics compensated for inferior conventional starfighter numbers through coordination and Force-guided interception. Grievous's fleet destroyed much of Dathomir's aerial capability in the massacre.", '#65a30d', ['nightsister-warriors', 'dathomir-clan-guard', 'dathomirian-orbital-shaman-guard']),
    ('other', 'navy', 'dathomirian-orbital-shaman-guard', 'Dathomirian Orbital Shaman Guard', 'Task force', 'Defense fleet', 'Orbital shaman guards combined Nightsister battle rituals with planetary defense platforms and improvised fighters to resist offworld invasion of Dathomir. Shaman guards invoked magick wards that confounded droid targeting systems temporarily. Imperial and Separatist fleets ultimately overwhelmed Dathomir through orbital bombardment rather than fighter superiority.', '#4d7c0f', ['nightsister-warriors', 'nightsister-swarm-squadron', 'nightbrother-warriors']),
    ('other', 'navy', 'shadow-collective-combined-fleet', 'Shadow Collective Combined Fleet', 'Task force', 'Task force', "Shadow Collective combined fleets merged Mandalorian assault wings, Pyke hauler escorts, and Black Sun frigates under Darth Maul's brief underworld empire during the Clone Wars. Combined fleet actions targeted spice routes, Mandalore, and rival syndicates simultaneously. The fleet dissolved when Maul's Mandalorian rule collapsed and syndicate allies defected.", '#dc2626', ['crimson-dawn-strike-flotilla', 'pyke-spice-hauler-convoy', 'black-sun-frigate-patrol']),
    ('sith-empire', 'army', 'sith-trooper-corps', 'Sith Trooper Corps', 'Infantry', None, "Red-armored Sith troopers formed the backbone of the Sith Imperial Army during the Great Galactic War and Cold War eras, enforcing Dark Council edicts from Dromund Kaas to conquered Core worlds. Trooper corps combined fanatical loyalty to the Emperor with brutal occupation doctrine across the Outer Rim. Their crimson armor marked Sith authority on every battlefield of the Old Republic era.", '#991b1b', ['sith-imperial-guard', 'sith-marauder-battalion', 'harrower-class-dreadnought']),
    ('sith-empire', 'army', 'sith-imperial-guard', 'Sith Imperial Guard', 'Elite guard', None, "The Sith Imperial Guard protected the Emperor, Dark Council members, and Korriban sanctuaries with force pikes, electrostaffs, and crimson robes echoing later Royal Guard traditions. Guard detachments accompanied Sith Lords into battle and executed traitors within the Imperial hierarchy. Their presence signaled that Sith politics were as deadly as open warfare.", '#7f1d1d', ['sith-trooper-corps', 'sith-inquisitor-enforcers', 'dromund-kaas-garrison']),
    ('sith-empire', 'army', 'sith-marauder-battalion', 'Sith Marauder Battalion', 'Heavy infantry', None, "Sith Marauders combined dark-side fury with heavy armor and vibroblades in shock assaults against Republic fortifications during the Great Galactic War. Marauder battalions spearheaded invasions of Alderaan, Balmorra, and other Core targets before the Treaty of Coruscant. Their berserker tactics made them among the most feared ground units in Sith service.", '#b91c1c', ['sith-trooper-corps', 'massassi-warrior-legion', 'sith-artillery-battery']),
    ('sith-empire', 'army', 'massassi-warrior-legion', 'Massassi Warrior Legion', 'Allied infantry', None, "Massassi warriors from Korriban and Yavin served Sith Lords as ceremonial guardians and brutal frontline infantry during ancient and revived Sith empires. Legions wielded Sith alchemy-enhanced weapons and fought with religious devotion to their dark masters. Massassi formations added primal terror to Sith combined-arms doctrine.", '#7f1d1d', ['sith-marauder-battalion', 'korriban-garrison', 'sith-trooper-corps']),
    ('sith-empire', 'army', 'sith-war-droid-legion', 'Sith War Droid Legion', 'Droid army', None, "Mark I and Mark IV Sith war droids supplemented organic infantry with tireless assault waves during the Great Galactic War and Jedi Civil War eras. War droid legions assaulted fortified positions where casualty rates would decimate flesh-and-blood battalions. Techno Union-derived designs mixed with Sith sorcerer modifications in later iterations.", '#991b1b', ['sith-trooper-corps', 'sith-marauder-battalion', 'sith-interceptor-wing']),
    ('sith-empire', 'army', 'sith-commando-brigade', 'Sith Commando Brigade', 'Special forces', None, "Sith commandos conducted sabotage, assassinations, and deep reconnaissance behind Republic lines during the Great Galactic War and subsequent Cold War skirmishes. Commandos operated in squads with mixed blaster, vibroblade, and limited Force training from Sith overseers. Their black-and-crimson armor distinguished elite operatives from standard troopers.", '#7f1d1d', ['sith-trooper-corps', 'sith-inquisitor-enforcers', 'sith-artillery-battery']),
    ('sith-empire', 'army', 'sith-artillery-battery', 'Sith Artillery Battery', 'Artillery', None, "Sith artillery batteries deployed self-propelled turbolaser platforms and missile launchers to soften Republic defenses before marauder assaults on worlds like Balmorra and Alderaan. Batteries coordinated with Harrower fleet bombardments for combined orbital-ground sieges. Sith artillery doctrine prioritized overwhelming destruction over precision.", '#b91b1c', ['sith-marauder-battalion', 'sith-war-droid-legion', 'sith-blockade-group']),
    ('sith-empire', 'army', 'sith-flametrooper-corps', 'Sith Flametrooper Corps', 'Specialist', None, "Sith flametroopers cleared bunkers, cave networks, and urban strongholds with flamethrowers during invasions of stubborn Republic-held worlds. Flametrooper corps were deployed when occupation required total denial rather than capture. Their scorched-earth tactics mirrored the Sith philosophy of power through fear.", '#991b1b', ['sith-trooper-corps', 'sith-marauder-battalion', 'korriban-garrison']),
    ('sith-empire', 'army', 'sith-inquisitor-enforcers', 'Sith Inquisitor Enforcers', 'Force users', None, "Inquisitor enforcers hunted Jedi fugitives, Force-sensitive dissidents, and rival Sith acolytes across conquered territories during the Old Republic era. Enforcers reported to both military command and Sith hierarchy, blurring lines between army and dark-side order. Their interrogation chambers became symbols of Imperial occupation.", '#7f1d1d', ['sith-imperial-guard', 'sith-commando-brigade', 'dromund-kaas-garrison']),
    ('sith-empire', 'army', 'korriban-garrison', 'Korriban Garrison', 'Garrison', None, "Korriban's garrison protected Sith tombs, academies, and pilgrimage routes sacred to the entire Sith tradition from Je'daii exile through the Great Galactic War. Garrison troops included Massassi warriors, Sith troopers, and dark-side acolytes in training. Any invasion of Korriban triggered the Empire's most fanatical defense.", '#991b1b', ['massassi-warrior-legion', 'sith-imperial-guard', 'korriban-defense-fleet']),
    ('sith-empire', 'army', 'dromund-kaas-garrison', 'Dromund Kaas Garrison', 'Garrison', None, "Dromund Kaas garrison forces secured the Imperial capital's rain-soaked cities, Dark Council spires, and orbital spaceports where the Sith Empire rebuilt after exile. Garrison legions doubled as parade troops and riot control during internal Sith power struggles. The capital's defenses reflected the Empire's claim to galactic supremacy.", '#7f1d1d', ['sith-imperial-guard', 'sith-trooper-corps', 'dromund-kaas-home-fleet']),
    ('sith-empire', 'army', 'sith-occupation-legion', 'Sith Occupation Legion', 'Occupation force', None, "Occupation legions held conquered Republic worlds after Great Galactic War offensives, maintaining curfews, labor camps, and dark-side tribunals that broke civilian resistance. Occupation doctrine mixed Sith trooper patrols with local collaborator militias and war droid garrisons. Liberation movements on Balmorra and Taris fought these legions for generations.", '#b91b1c', ['sith-trooper-corps', 'sith-war-droid-legion', 'sith-blockade-group']),
    ('sith-empire', 'army', 'sith-speeder-patrol-corps', 'Sith Speeder Patrol Corps', 'Reconnaissance', None, "Sith speeder patrols maintained rapid response capability across urban occupation zones and frontier garrisons with repulsorcraft armed for anti-infantry sweeps. Patrol corps hunted Republic resistance cells and smuggler networks on conquered worlds. Speeder units coordinated with interceptor wings for combined air-ground operations.", '#991b1b', ['sith-commando-brigade', 'sith-occupation-legion', 'sith-interceptor-wing']),
    ('sith-empire', 'army', 'sith-siege-battalion', 'Sith Siege Battalion', 'Siege', None, "Siege battalions deployed heavy breaching equipment, war droids, and sustained artillery against Republic fortress worlds during the Great Galactic War's longest campaigns. Siege doctrine on Balmorra and Corellia demonstrated Sith willingness to grind down defenses over months rather than accept stalemate. Battalion survivors often bore alchemical scars from dark-side battlefield rituals.", '#7f1d1d', ['sith-artillery-battery', 'sith-war-droid-legion', 'harrower-class-dreadnought']),
    ('sith-empire', 'army', 'sith-punitive-expeditionary-force', 'Sith Punitive Expeditionary Force', 'Task force', 'Task force', "Punitive expeditionary forces answered rebellions with overwhelming retribution—bombing cities, executing hostages, and leaving worlds as warnings to neighboring systems. These task forces reported directly to Sith Lords rather than conventional military command. Their campaigns defined the terror that Republic propaganda used to rally citizens against the Empire.", '#991b1b', ['sith-occupation-legion', 'sith-flametrooper-corps', 'sith-blockade-group']),
    ('sith-empire', 'navy', 'harrower-class-dreadnought', 'Harrower-class Dreadnought', 'Capital ship', 'Dreadnought', "Harrower-class dreadnoughts formed the backbone of the Sith Imperial Navy during the Great Galactic War, combining turbolaser broadsides with massive starfighter complements. Dreadnoughts led invasions of the Core and blockaded Republic supply routes across the Mid Rim. Their crimson hull markings announced Sith fleet arrival before the first volley fired.", '#991b1b', ['terminus-class-destroyer', 'sith-interceptor-wing', 'sith-fleet-command']),
    ('sith-empire', 'navy', 'terminus-class-destroyer', 'Terminus-class Destroyer', 'Escort ship', 'Destroyer', "Terminus-class destroyers screened Harrower battle groups and conducted independent raids on Republic convoys during the Great Galactic War. Destroyer squadrons used aggressive forward tactics learned from Mandalorian allies and Sith naval academies on Dromund Kaas. Their wedge profiles became standard Sith escort design for centuries.", '#7f1d1d', ['harrower-class-dreadnought', 'sith-bomber-wing', 'sith-blockade-group']),
    ('sith-empire', 'navy', 'sith-interceptor-wing', 'Sith Interceptor Wing', 'Starfighter unit', 'Starfighter wing', "Sith interceptor wings flew twin-boom starfighters in aggressive formations that hunted Republic Aurek and S-250 fighters during orbital battles above Alderaan, Balmorra, and Coruscant. Interceptor pilots trained under Sith discipline with zero tolerance for retreat. Wings launched from Harrower hangars in waves designed to overwhelm Republic fighter screens.", '#b91b1c', ['sith-bomber-wing', 'harrower-class-dreadnought', 'sith-fleet-command']),
    ('sith-empire', 'navy', 'sith-bomber-wing', 'Sith Bomber Wing', 'Starfighter unit', 'Bomber wing', "Sith bomber wings delivered proton torpedoes and concussion missiles against Republic capital ships and planetary shields during the Great Galactic War. Bombers coordinated with Harrower dreadnoughts to crack blockades before troop transports landed occupation legions. Bomber losses were acceptable when they opened paths for marauder assaults.", '#991b1b', ['sith-interceptor-wing', 'harrower-class-dreadnought', 'sith-siege-battalion']),
    ('sith-empire', 'navy', 'mark-vi-supremacy-class', 'Mark VI Supremacy-class Ultra Star Destroyer', 'Capital ship', 'Super capital', "Mark VI Supremacy-class vessels represented the Sith Empire's ultimate naval ambition—city-sized warships capable of subjugating star systems alone during the height of Imperial power. Ultra Star Destroyers served as mobile throne rooms for Sith Lords and terror weapons against Core worlds. Few were built, but their legend persisted in Republic nightmares.", '#7f1d1d', ['harrower-class-dreadnought', 'sith-fleet-command', 'dromund-kaas-home-fleet']),
    ('sith-empire', 'navy', 'sith-fleet-command', 'Sith Imperial Fleet Command', 'Task force', 'Task force', "Imperial Fleet Command coordinated Harrower battle groups, Terminus escorts, and interceptor wings across the Great Galactic War theater under Dark Council naval strategy. Fleet Command's victory at Coruscant's orbit forced the Treaty of Coruscant that reshaped the galaxy. Admirals served at the pleasure of Sith Lords who could kill them for any defeat.", '#991b1b', ['harrower-class-dreadnought', 'sith-interceptor-wing', 'sith-blockade-group']),
    ('sith-empire', 'navy', 'korriban-defense-fleet', 'Korriban Defense Fleet', 'Task force', 'Defense fleet', "Korriban's defense fleet protected the Sith holy world with Harrower dreadnoughts, interceptor wings, and orbital platforms armed against Jedi retrieval missions and Republic reprisals. The fleet's presence ensured Korriban remained inviolate even when the Empire lost ground elsewhere. Pilgrimage convoys received escort from this fleet during Sith ascension rituals.", '#7f1d1d', ['korriban-garrison', 'harrower-class-dreadnought', 'sith-imperial-guard']),
    ('sith-empire', 'navy', 'dromund-kaas-home-fleet', 'Dromund Kaas Home Fleet', 'Task force', 'Defense fleet', "Dromund Kaas home fleet guarded the Imperial capital with the largest concentration of Harrower dreadnoughts outside active invasion corridors. Home fleet admirals answered directly to the Emperor and Dark Council, not regional Moffs. Any threat to the capital triggered mobilization of the Empire's entire reserve navy.", '#991b1b', ['dromund-kaas-garrison', 'harrower-class-dreadnought', 'sith-fleet-command']),
    ('sith-empire', 'navy', 'sith-blockade-group', 'Sith Blockade Group', 'Task force', 'Blockade fleet', "Sith blockade groups encircled Republic worlds with Terminus destroyers and interceptor wings, starving populations until surrender or annihilation during the Great Galactic War. Blockades on the Rim preceded Core invasions by years of economic warfare. Breakouts required Republic fleets larger than most sectors could muster alone.", '#b91b1c', ['terminus-class-destroyer', 'sith-interceptor-wing', 'sith-occupation-legion']),
    ('sith-empire', 'navy', 'sith-transport-convoy', 'Sith Imperial Transport Convoy', 'Support ship', 'Transport', "Imperial transport convoys moved Sith troopers, war droids, and occupation supplies from Dromund Kaas foundries to invasion beaches across the galaxy. Convoys received heavy escort after Republic raiders learned to strike logistics chains. Transport security became a career path for officers seeking Dark Council favor.", '#7f1d1d', ['sith-trooper-corps', 'sith-war-droid-legion', 'terminus-class-destroyer']),
    ('sith-empire', 'navy', 'sith-hypergate-strike-group', 'Sith Hypergate Strike Group', 'Task force', 'Strike force', "Hypergate strike groups exploited ancient Rakata and Sith Empire hypergate technology for surprise fleet arrivals behind Republic lines during the Great Galactic War. Strike groups combined Terminus destroyers with commando brigades for decapitation raids on shipyards and Senate installations. Republic counterintelligence spent fortunes hunting hypergate coordinates.", '#991b1b', ['sith-commando-brigade', 'terminus-class-destroyer', 'sith-fleet-command']),
    ('sith-empire', 'navy', 'sith-ambassador-escort-squadron', 'Sith Diplomatic Escort Squadron', 'Escort ship', 'Corvette', "Diplomatic escort squadrons protected Sith emissaries during the Cold War's uneasy truce, bristling with weapons despite treaty protocols limiting fleet movements. Escorts shadowed Republic negotiators on Korriban and Dromund Kaas with implicit threats. Any 'accident' during diplomacy could reignite full-scale war instantly.", '#7f1d1d', ['dromund-kaas-home-fleet', 'sith-imperial-guard', 'sith-interceptor-wing']),
    ('old-republic', 'army', 'republic-trooper-corps', 'Republic Trooper Corps', 'Infantry', None, "Republic troopers in blue-and-white armor formed the standard infantry of the Old Republic military during the Great Galactic War, Mandalorian Wars, and Jedi Civil War eras. Trooper corps defended Core worlds, invaded Sith-held territories, and garrisoned Taris after reconstruction. Their discipline varied by era but remained the democratic galaxy's primary ground force.", '#2563eb', ['republic-commandos', 'republic-marine-corps', 'hammerhead-class-cruiser-group']),
    ('old-republic', 'army', 'republic-commandos', 'Republic Commandos', 'Special forces', None, "Republic commando squads executed precision strikes with modular armor and coordinated breaching tactics during the Mandalorian Wars and Great Galactic War. Commandos served under Jedi generals Revan and Malak before those same leaders turned Sith. Commando veterans later split between Republic loyalty and Sith recruitment during the Jedi Civil War.", '#1d4ed8', ['republic-trooper-corps', 'republic-special-forces', 'republic-transport-command']),
    ('old-republic', 'army', 'republic-marine-corps', 'Republic Marine Corps', 'Marines', None, "Republic marines secured beachheads during orbital invasions and boarded Sith dreadnoughts during desperate fleet actions of the Great Galactic War. Marine corps trained for zero-gravity corridor combat and rapid deployment from Hammerhead cruisers. Their blue armor with gold accents marked the Republic's expeditionary capability.", '#3b82f6', ['republic-trooper-corps', 'republic-commandos', 'endar-spire-assault-group']),
    ('old-republic', 'army', 'republic-special-forces', 'Republic Special Forces', 'Special forces', None, "Republic Special Forces operated behind Sith lines with sabotage, intelligence gathering, and assassination missions during the Great Galactic War and Cold War. SpecForce units included both organic soldiers and trusted droid auxiliaries on missions too sensitive for regular troopers. Their successes on Balmorra and Corellia became Republic propaganda legends.", '#2563eb', ['republic-commandos', 'republic-trooper-corps', 'republic-artillery-battery']),
    ('old-republic', 'army', 'republic-artillery-battery', 'Republic Artillery Battery', 'Artillery', None, "Republic artillery batteries deployed mobile turbolaser platforms and missile systems to support trooper advances against Sith marauders and Mandalorian shock troops. Batteries on Ruusan and Jabiim proved decisive in breaking sieges that infantry alone could not win. Artillery coordination with Hammerhead fleet bombardments defined Old Republic combined-arms doctrine.", '#1d4ed8', ['republic-trooper-corps', 'republic-combat-engineers', 'hammerhead-class-cruiser-group']),
    ('old-republic', 'army', 'republic-combat-engineers', 'Republic Combat Engineers', 'Combat engineers', None, "Republic combat engineers built fortifications, breached Sith bunker complexes, and maintained forward supply depots under fire across three wars spanning the Old Republic era. Engineers on Telos IV rebuilt the Citadel Station orbital restoration project after Sith devastation. Their work kept Republic armies mobile when Sith occupation forces expected stalemate.", '#3b82f6', ['republic-artillery-battery', 'republic-trooper-corps', 'republic-transport-command']),
    ('old-republic', 'army', 'republic-scout-corps', 'Republic Scout Corps', 'Reconnaissance', None, "Republic scouts operated speeder bikes, light repulsorcraft, and stealth reconnaissance pods to map Sith troop movements before major offensives during the Great Galactic War. Scout corps intelligence prevented ambushes on Taris and guided Hammerhead fleets through mined hyperspace routes. Scouts often worked alongside Jedi advance parties.", '#2563eb', ['republic-trooper-corps', 'republic-special-forces', 'republic-aurek-fighter-wing']),
    ('old-republic', 'army', 'republic-flametrooper-platoons', 'Republic Flametrooper Platoons', 'Specialist', None, "Republic flametrooper platoons cleared underground Sith bunkers, cave networks on Dxun, and urban strongholds during the Mandalorian Wars and Great Galactic War. Flametroopers wore heat-resistant armor against backlash from their own weapons in close quarters. Platoons were deployed sparingly due to collateral damage concerns from Senate oversight.", '#1d4ed8', ['republic-trooper-corps', 'republic-marine-corps', 'republic-artillery-battery']),
    ('old-republic', 'army', 'republic-jedi-knight-detachments', 'Republic Jedi Knight Detachments', 'Command', None, "Jedi Knight detachments served as generals and morale symbols for Republic armies during the Great Galactic War and Mandalorian Wars before the order's catastrophic losses. Detachments combined lightsaber expertise with strategic command authority that regular officers lacked. Revan and Malak's fall from Jedi generals to Sith Lords traumatized the Republic military for generations.", '#22c55e', ['republic-trooper-corps', 'republic-commandos', 'open-circle-old-republic-fleet']),
    ('old-republic', 'army', 'republic-garrison-legion', 'Republic Garrison Legion', 'Garrison', None, "Republic garrison legions held pacified worlds after Sith retreats, maintaining order on Taris, Telos, and Outer Rim colonies during reconstruction eras. Garrisons mixed troopers, local militia, and Jedi advisors depending on the sector. Corruption and understaffing made some garrisons vulnerable to Sith resurgence between major wars.", '#2563eb', ['republic-trooper-corps', 'republic-combat-engineers', 'coruscant-defense-legion']),
    ('old-republic', 'army', 'republic-airborne-company', 'Republic Airborne Company', 'Airborne', None, "Republic airborne companies dropped from gunships and transport shuttles to seize objectives behind Sith lines during rapid offensive campaigns of the Great Galactic War. Airborne doctrine borrowed from Mandalorian tactics after the Republic adopted enemy innovations. Companies at Dxun and Althir demonstrated Republic adaptability under Jedi leadership.", '#3b82f6', ['republic-commandos', 'republic-marine-corps', 'republic-aurek-fighter-wing']),
    ('old-republic', 'army', 'republic-medical-corps', 'Republic Medical Corps', 'Support', None, "Republic medical corps evacuated wounded from battlefields across Ruusan, Jabiim, and Core worlds with field hospitals aboard Hammerhead cruisers and Citadel Station. Medics treated Republic troopers, Jedi, and even Mandalorian prisoners under wartime conventions that Sith forces ignored. Medical corps shortages during the Mandalorian Wars fueled public outrage on Coruscant.", '#1d4ed8', ['republic-trooper-corps', 'republic-garrison-legion', 'pelta-class-support-group']),
    ('old-republic', 'army', 'coruscant-defense-legion', 'Coruscant Defense Legion', 'Garrison', None, "Coruscant defense legions protected the Senate, Jedi Temple forerunners, and planetary shields during the Sacking of Coruscant and subsequent Cold War tensions. Defense legions were among the best-equipped Republic units, though the Sacking revealed catastrophic strategic failures at the naval level. Legion survivors rebuilt Coruscant's ground defenses over decades.", '#2563eb', ['republic-trooper-corps', 'republic-jedi-knight-detachments', 'coruscant-home-defense-squadron']),
    ('old-republic', 'army', 'ruusan-campaign-army', 'Ruusan Campaign Army', 'Task force', 'Task force', "The Ruusan campaign army fought the final New Sith Wars battles that ended with Darth Bane's survival and the Rule of Two's inception. Army units endured thought bomb devastation and brotherhood-of-darkness collapse on the battlefield. Ruusan's scars reshaped both Jedi and Sith institutions for a millennium.", '#1d4ed8', ['republic-trooper-corps', 'republic-jedi-knight-detachments', 'republic-artillery-battery']),
    ('old-republic', 'army', 'mandalorian-war-veteran-battalion', 'Mandalorian War Veteran Battalion', 'Veteran infantry', None, "Veteran battalions of Republic soldiers who survived the Mandalorian Wars carried brutal combat experience into the Jedi Civil War against former commanders Revan and Malak. Veterans often distrusted Jedi leadership after Malachor V's mass shadow generator deployment. Battalion loyalty fractured when Revan returned as a conquering Sith Lord.", '#3b82f6', ['republic-commandos', 'republic-trooper-corps', 'republic-jedi-knight-detachments']),
    ('old-republic', 'navy', 'hammerhead-class-cruiser-group', 'Hammerhead-class Cruiser Group', 'Capital ship', 'Cruiser', "Hammerhead-class cruiser groups formed the backbone of Old Republic fleet actions during the Mandalorian Wars and Jedi Civil War, including the Endar Spire's final battle above Taris. Cruiser groups rammed Sith vessels when turbolasers failed and troop transports needed escort. Hammerhead silhouettes symbolized Republic resilience across KOTOR-era conflicts.", '#2563eb', ['endar-spire-assault-group', 'republic-aurek-fighter-wing', 'open-circle-old-republic-fleet']),
    ('old-republic', 'navy', 'endar-spire-assault-group', 'Endar Spire Assault Group', 'Task force', 'Flagship', "The Endar Spire assault group represented Republic rapid-deployment doctrine—Hammerhead cruisers, Aurek fighters, and marine detachments inserted into crisis zones like the Taris blockade. The Endar Spire's destruction launched Revan's amnesia arc and the Jedi Civil War's final phase. Assault groups prioritized getting Jedi and troopers to the fight over heavy capital ship duels.", '#1d4ed8', ['hammerhead-class-cruiser-group', 'republic-marine-corps', 'republic-aurek-fighter-wing']),
    ('old-republic', 'navy', 'republic-aurek-fighter-wing', 'Aurek Tactical Starfighter Wing', 'Starfighter unit', 'Starfighter wing', "Aurek tactical starfighters provided Old Republic fleets with agile interceptors during the Great Galactic War and Mandalorian Wars before later designs superseded them. Aurek wings escorted Hammerhead cruisers and hunted Sith interceptors in tight orbital engagements. Pilot aces on Coruscant and Telos became recruitment symbols for the Republic Navy.", '#3b82f6', ['hammerhead-class-cruiser-group', 'republic-bomber-wing', 'open-circle-old-republic-fleet']),
    ('old-republic', 'navy', 'republic-bomber-wing', 'Republic Bomber Wing', 'Starfighter unit', 'Bomber wing', "Republic bomber wings delivered ordnance against Sith Harrower dreadnoughts and planetary shields during the Great Galactic War's largest fleet battles. Bombers coordinated with Hammerhead ramming tactics to crack hull breaches for marine boarding parties. Wing losses were heavy but necessary against Sith numerical superiority.", '#2563eb', ['republic-aurek-fighter-wing', 'hammerhead-class-cruiser-group', 'republic-marine-corps']),
    ('old-republic', 'navy', 'thranta-class-corvette-squadron', 'Thranta-class Corvette Squadron', 'Escort ship', 'Corvette', "Thranta-class corvettes escorted Hammerhead battle groups and conducted independent patrols along Republic hyperlanes threatened by Sith raiders during the Great Galactic War. Corvette squadrons from Core shipyards on Coruscant and Anaxes maintained trade route security. Their compact profiles suited rapid response better than heavy cruisers.", '#1d4ed8', ['hammerhead-class-cruiser-group', 'republic-aurek-fighter-wing', 'republic-blockade-interdiction-group']),
    ('old-republic', 'navy', 'valor-class-cruiser-group', 'Valor-class Cruiser Group', 'Capital ship', 'Cruiser', "Valor-class cruisers served as command vessels for Republic fleet admirals during the Great Galactic War and Cold War, combining firepower with advanced communications for multi-system campaigns. Cruiser groups led counteroffensives after the Sacking of Coruscant. Valor-class hulls remained in reserve fleets until the Clone Wars era refits.", '#2563eb', ['hammerhead-class-cruiser-group', 'open-circle-old-republic-fleet', 'coruscant-home-defense-squadron']),
    ('old-republic', 'navy', 'open-circle-old-republic-fleet', 'Old Republic Open Circle Fleet', 'Task force', 'Task force', "The Old Republic Open Circle Fleet coordinated multi-sector naval campaigns during the Great Galactic War under Jedi admirals and Senate-appointed commanders. Open Circle doctrine emphasized combined cruiser, fighter, and marine operations against Sith invasion fleets. The insignia later inspired Clone Wars-era fleet naming as historical homage.", '#3b82f6', ['hammerhead-class-cruiser-group', 'republic-jedi-knight-detachments', 'republic-aurek-fighter-wing']),
    ('old-republic', 'navy', 'coruscant-home-defense-squadron', 'Coruscant Home Defense Squadron', 'Task force', 'Defense fleet', "Coruscant home defense squadrons failed to prevent the Sacking of Coruscant but rebuilt into the galaxy's heaviest system defense force during the Cold War. Squadrons mixed Valor cruisers, Hammerhead veterans, and Aurek wings under strict Senate oversight. Defense funding became the Republic's largest military expenditure after the treaty.", '#2563eb', ['coruscant-defense-legion', 'valor-class-cruiser-group', 'republic-aurek-fighter-wing']),
    ('old-republic', 'navy', 'republic-blockade-interdiction-group', 'Republic Blockade Interdiction Group', 'Task force', 'Interdiction fleet', "Blockade interdiction groups broke Sith encirclements of Republic worlds with coordinated cruiser strikes and fighter sweeps during the Great Galactic War. Groups specialized in relieving besieged colonies when larger fleets were engaged elsewhere. Interdiction successes on Balmorra and Alderaan bought time for diplomatic negotiations.", '#1d4ed8', ['thranta-class-corvette-squadron', 'hammerhead-class-cruiser-group', 'republic-trooper-corps']),
    ('old-republic', 'navy', 'republic-transport-command', 'Republic Transport Command', 'Support ship', 'Transport', "Republic transport command moved millions of troopers, supplies, and refugees across war-torn hyperlanes during the Mandalorian Wars and Great Galactic War. Transport fleets included converted merchant hulls and dedicated military cargo ships escorted by Thranta corvettes. Logistics failures on remote Rim worlds often decided campaigns before battles began.", '#3b82f6', ['republic-trooper-corps', 'republic-combat-engineers', 'thranta-class-corvette-squadron']),
    ('old-republic', 'navy', 'pelta-class-support-group', 'Republic Medical Support Group', 'Support ship', 'Frigate', "Republic medical support groups operated Pelta-class frigates as hospital ships evacuating wounded from Ruusan, Dxun, and Core battlefields across the Old Republic era. Support groups observed wartime medical conventions that Sith forces violated with targeted strikes. Medical frigate crews included Jedi healers and Republic surgeons working side by side.", '#2563eb', ['republic-medical-corps', 'hammerhead-class-cruiser-group', 'republic-transport-command']),
    ('old-republic', 'navy', 'republic-carrier-battle-group', 'Republic Carrier Battle Group', 'Task force', 'Carrier group', "Republic carrier battle groups launched sustained starfighter campaigns against Sith dreadnoughts when direct cruiser engagement proved too costly during the Great Galactic War. Battle groups combined Valor-class command ships with multiple Aurek and bomber wings. Carrier doctrine influenced later Republic Venator designs millennia afterward.", '#1d4ed8', ['valor-class-cruiser-group', 'republic-aurek-fighter-wing', 'republic-bomber-wing']),
]
